INSERT INTO lesson_sources (lesson_id, source_name, source_url, source_type) VALUES
(@lesson1_id, 'Scarleteen - Not Everything You Wanted To Know About Puberty', 'https://www.scarleteen.com/read/bodies/not-everything-you-wanted-know-about-puberty-pretty-darn-close', 'website');
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson1_id, 'Tuổi dậy thì là gì?', 1);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có cảm giác cơ thể và tâm trạng của mình dạo này thay đổi nhanh như thời tiết không?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Dậy thì là giai đoạn chuyển tiếp kỳ diệu từ một đứa trẻ để trở thành một người trưởng thành về mặt sinh học.", "Đây là lúc cơ thể bắt đầu sản sinh ra các hormone sinh dục, kích hoạt một loạt thay đổi lớn từ chiều cao, vóc dáng đến cảm xúc.", "Quá trình này diễn ra hoàn toàn tự nhiên và ai cũng phải bước qua để lớn lên."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống bất ngờ", "body": "Linh bỗng nhận ra chiếc quần jeans yêu thích mặc tháng trước hôm nay đã ngắn cũn cỡn. Cùng lúc đó, Linh cảm thấy mình dễ xúc động và bực bội hơn chỉ vì những lý do nhỏ nhặt trong nhà. Linh lo lắng không biết mình có bị làm sao không."}', 3),
(@ml_id, 'interaction', '{"question": "Linh nên hiểu những thay đổi này như thế nào?", "choices": [{"text": "Chắc chắn là cơ thể mình đang có vấn đề bất thường rồi, cần đi khám bác sĩ gấp.", "correct": false, "emoji": "🛑"}, {"text": "Đây là dấu hiệu cho thấy nút dậy thì của mình đã được kích hoạt, mọi thứ đang tiến triển tự nhiên.", "correct": true, "emoji": "💚"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có nhận ra sự thay đổi lớn nhất nào của bản thân trong vài tháng qua không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Dậy thì không phải là một căn bệnh, đó là hành trình trưởng thành của cơ thể bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson1_id, 'Ai kích hoạt nút dậy thì?', 2);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có biết một vùng não nhỏ xíu chính là tổng chỉ huy đứng sau toàn bộ cơn bão dậy thì?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Hệ thống nội tiết của bạn, dẫn đầu bởi vùng hạ đồi và tuyến yên trong não, phát tín hiệu đánh thức cơ thể.", "Chúng giải phóng các hormone hướng sinh dục, thúc đẩy tinh hoàn ở nam sản xuất testosterone và buồng trứng ở nữ sản xuất estrogen.", "Các hormone này chính là những sứ giả hóa học đi khắp cơ thể để tạo nên những thay đổi đặc trưng."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống cọc cằn", "body": "Nam bỗng dưng cảm thấy nóng nảy, muốn quát tháo khi mẹ nhắc nhở dọn dẹp phòng, dù bình thường Nam rất nghe lời. Nam tự trách mình dạo này biến thành đứa con tồi tệ."}', 3),
(@ml_id, 'interaction', '{"question": "Theo bạn, hành vi dễ cọc cằn đột ngột của Nam do đâu?", "choices": [{"text": "Do tính cách của Nam đã thay đổi tiêu cực và Nam không còn tôn trọng bố mẹ nữa.", "correct": false, "emoji": "🛑"}, {"text": "Do hormone sinh dục dâng cao kích thích vùng não cảm xúc nhạy cảm hơn bình thường.", "correct": true, "emoji": "💚"}]}', 4),
(@ml_id, 'reflection', '{"question": "Gần đây bạn có từng cảm thấy cảm xúc của mình bị đẩy lên quá mức chỉ vì một chuyện nhỏ không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Hormone đang làm việc của chúng, việc của bạn là học cách làm bạn với chúng."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson1_id, 'Cột mốc khác nhau', 3);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Tại sao đứa bạn cùng bàn đã cao lớn vổng lên trong khi mình vẫn lẹt đẹt như học sinh tiểu học?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Không có một lịch trình dậy thì chung áp dụng cho tất cả mọi người.", "Dậy thì thường bắt đầu trong khoảng từ 8 đến 14 tuổi đối với nữ, và từ 9 đến 15 tuổi đối với nam.", "Tốc độ dậy thì nhanh hay chậm phụ thuộc rất lớn vào gen di truyền, dinh dưỡng và môi trường sống của mỗi người."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống so sánh", "body": "Đức thấy lo lắng và tự ti vô cùng khi các bạn nam trong lớp đều đã vỡ giọng và cao trên 1m65, còn mình vẫn mang giọng trẻ con và thấp bé nhất lớp. Đức nghĩ mình sẽ mãi không lớn được."}', 3),
(@ml_id, 'interaction', '{"question": "Đức nên tự nhủ điều gì để giảm bớt sự lo âu về tốc độ phát triển của mình?", "choices": [{"text": "Mọi người có chiếc đồng hồ sinh học riêng, sớm hay muộn thì mình cũng sẽ bước vào giai đoạn tăng tốc thôi.", "correct": true, "emoji": "💚"}, {"text": "Chắc do mình lười vận động nên mới còi cọc thế, phải uống thật nhiều thực phẩm chức năng tăng chiều cao ngay.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có từng cảm thấy áp lực khi so sánh tốc độ lớn của mình với các bạn xung quanh chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Cơ thể bạn không chạy đua với ai cả, hãy để nó lớn lên theo nhịp điệu tự nhiên của riêng mình."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson1_id, 'Tình huống thực tế', 4);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn sẽ đối phó thế nào với cơn giận dữ hay sự nhạy cảm quá đà xuất hiện bất thình lình?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Dậy thì không chỉ biến đổi thể xác mà còn tạm thời tái cấu trúc lại bộ não của bạn.", "Vùng hạch hạnh nhân (xử lý cảm xúc) phát triển nhanh hơn vỏ não trước trán (kiểm soát hành vi và suy nghĩ logic).", "Điều này giải thích tại sao bạn dễ cảm thấy yếu đuối, nhạy cảm hay tức giận vô cớ."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống bùng nổ", "body": "Vy đang làm bài tập thì bị em trai vô tình làm xáo trộn đống tài liệu. Vy bỗng thấy ngực nghẹn lại, nổi giận lôi đình và quát mắng em thậm tệ. Sau đó Vy ngồi thụp xuống khóc nức nở vì thấy hối hận."}', 3),
(@ml_id, 'interaction', '{"question": "Vy nên làm gì để xoa dịu bản thân sau cơn bùng nổ cảm xúc đó?", "choices": [{"text": "Nhận ra cảm xúc quá đà là do biến động hormone, hít thở sâu, xin lỗi em trai và tự ôm lấy chính mình.", "correct": true, "emoji": "💚"}, {"text": "Tự trách móc mình là một người chị tồi tệ và nhốt mình trong phòng kín cả ngày để suy nghĩ tiêu cực.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Lần gần nhất bạn giận dữ vô cớ là khi nào? Bạn có nhận ra tín hiệu báo trước của cơ thể không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Cảm xúc mạnh mẽ giống như một cơn sóng, hãy học cách lướt sóng thay vì để nó nhấn chìm."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson1_id, 'Hành động tự tin', 5);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có muốn sở hữu chiếc chìa khóa vạn năng giúp vượt qua những bỡ ngỡ tuổi dậy thì?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Chìa khóa lớn nhất để đi qua tuổi dậy thì một cách an lành chính là sự trang bị kiến thức và tự tin chia sẻ.", "Việc tìm hiểu trước các thay đổi giúp bạn không bị hoang mang khi chúng thực sự xảy ra.", "Nói chuyện với một người lớn đáng tin cậy hoặc chuyên gia sức khỏe giúp bạn gỡ rối những thắc mắc thầm kín."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống ngượng ngùng", "body": "Khoa bắt đầu mọc những sợi râu tơ đầu tiên và giọng nói trở nên khàn khàn khó nghe. Khoa thấy ngượng ngùng, không dám mở miệng phát biểu bài trên lớp và cũng không dám hỏi bố cách cạo râu."}', 3),
(@ml_id, 'interaction', '{"question": "Khoa nên làm gì để vượt qua sự ngại ngùng này?", "choices": [{"text": "Chủ động mở lời với bố: ''Bố ơi, râu con mọc nhiều rồi, bố chỉ con cách dùng dao cạo an toàn nhé!''.", "correct": true, "emoji": "💚"}, {"text": "Tìm cách tự lấy kéo cắt râu lén lút vì sợ bố cười chê mình nứt mắt đã đòi làm người lớn.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Ai là người lớn đáng tin cậy nhất mà bạn có thể thoải mái chia sẻ những rắc rối tuổi dậy thì?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Yêu cầu sự giúp đỡ hay hướng dẫn là bước đi đầu tiên của sự tự lập."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson1_id, 'Tự vấn bản thân', 6);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có sẵn sàng gửi một lời cảm ơn đến cơ thể đang nỗ lực lớn lên mỗi ngày của mình?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Dậy thì là một quá trình tốn nhiều năng lượng của cơ thể.", "Cơ thể bạn đang phải làm việc cật lực để phân chia tế bào, kéo dài xương và điều hòa các tuyến hormone mới.", "Lắng nghe, thấu cảm và kiên nhẫn với chính mình là thái độ yêu thương bản thân tốt nhất lúc này."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống mệt mỏi", "body": "Mai cảm thấy cơ thể luôn trong trạng thái buồn ngủ, uể oải dù ngủ đủ 8 tiếng. Mai tự trách mình lười biếng và ép bản thân thức khuya học bài để bù lại thời gian."}', 3),
(@ml_id, 'interaction', '{"question": "Mai nên đối xử với cơ thể uể oải của mình như thế nào?", "choices": [{"text": "Lắng nghe tín hiệu cơ thể, sắp xếp nghỉ ngơi xen kẽ và tự nhủ: ''Cơ thể mình đang bận lớn, mệt mỏi chút là bình thường''.", "correct": true, "emoji": "💚"}, {"text": "Uống thật nhiều nước tăng lực để ép bộ não tỉnh táo làm việc công suất cao liên tục.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Hôm nay, bạn muốn dành sự bao dung nào cho những khuyết điểm hay sự mệt mỏi của bản thân?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Kiên nhẫn với sự phát triển của chính mình là biểu hiện của lòng trắc ẩn sâu sắc."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson1_id, 'Bài kiểm tra: Thử thách tổng kết', 99);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Chào mừng bạn đến với Thử thách Tổng kết bài học ''Giải mã tuổi dậy thì''! Hãy bình tĩnh vượt qua các thử thách về phát triển thể chất và tinh thần để tự tin làm chủ cơ thể."}', 1),
(@ml_id, 'scenario-choice', '{"title": "Hành trình tự tin và ứng phó áp lực tăng trưởng", "startNode": "step1", "nodes": {"step1": {"text": "Vy hoang mang vì chiều cao chững lại không tăng thêm trong 3 tháng qua, bạn bè khuyên Vy uống thuốc hormone tăng chiều cao thần tốc mua trên mạng để mau đuổi kịp các bạn.", "choices": [{"text": "Tin bạn, đặt mua ngay lọ thuốc hormone tăng chiều cao trôi nổi về tự uống.", "nextNode": "fail_drugs"}, {"text": "Tìm hiểu thông tin khoa học, nhận thức chiều cao phát triển theo đợt tự nhiên và kiên nhẫn theo dõi tiếp.", "nextNode": "step2"}]}, "step2": {"text": "Vy bắt đầu chú ý ăn uống đầy đủ chất và tập thể thao lành mạnh. Tuy nhiên, một bạn nam cùng lớp chế giễu gọi Vy là \"nấm lùn di động\" trước cả lớp.", "choices": [{"text": "Xấu hổ cúi đầu chịu đựng, quyết định nhịn ăn sáng để cơ thể gầy thon thả hơn cho đỡ lộ chiều cao thấp.", "nextNode": "fail_diet"}, {"text": "Nhìn thẳng bạn đó, bình tĩnh đáp: \"Chiều cao của tớ lớn theo nhịp tự nhiên của tớ, mong cậu tôn trọng ngoại hình người khác\" rồi tiếp tục đi bộ.", "nextNode": "step3"}]}, "step3": {"text": "Vy tập luyện kiên trì nhưng mẹ Vy sốt ruột tự ý mua cho Vy các loại thực phẩm chức năng kích thích hormone tăng trưởng do một người quen giới thiệu.", "choices": [{"text": "Nghe lời mẹ uống thuốc kích thích hormone tăng trưởng không nhãn mác y tế.", "nextNode": "fail_unverified"}, {"text": "Khuyên mẹ đưa mình đi khám bác sĩ dinh dưỡng hoặc nội tiết để đo tuổi xương và nhận tư vấn y khoa chính thống.", "nextNode": "step4"}]}, "step4": {"text": "Sau khi đi khám và được bác sĩ khuyên tập thể dục nhẹ nhàng, Vy băn khoăn nên chọn môn thể thao nào thích hợp nhất để phát triển hệ xương.", "choices": [{"text": "Đăng ký các bài tập tạ cực nặng quá sức tại phòng gym để ép xương phát triển nhanh.", "nextNode": "fail_heavy"}, {"text": "Tham gia bơi lội, đạp xe hoặc nhảy dây điều độ 30-45 phút mỗi ngày.", "nextNode": "step5"}]}, "step5": {"text": "Vy thấy một quảng cáo trên mạng cam kết tăng 5cm trong 1 tháng bằng phương pháp bẻ khớp nắn xương vật lý trị liệu dậy thì.", "choices": [{"text": "Bỏ qua quảng cáo lừa đảo, kiên trì tập luyện và sinh hoạt lành mạnh theo khoa học.", "nextNode": "success_end"}, {"text": "Đòi mẹ đưa đến trung tâm nắn xương không có chứng chỉ y tế để thực hiện bẻ khớp.", "nextNode": "fail_bone"}]}, "success_end": {"text": "🎉 Xuất sắc! Bạn đã biết cách tôn trọng nhịp độ phát triển của cơ thể, kiên định trước lời trêu chọc và tìm nguồn tư vấn y khoa chính xác khi cần.", "isEnd": true, "isSuccess": true}, "fail_drugs": {"text": "❌ Chưa đúng! Tự ý uống các thuốc hormone trôi nổi cực kỳ nguy hiểm, có thể làm đóng sụn xương sớm khiến bạn lùn vĩnh viễn, đồng thời gây hại nghiêm trọng cho gan và thận.", "isEnd": true, "isSuccess": false}, "fail_diet": {"text": "❌ Chưa đúng! Nhịn ăn sáng làm cơ thể thiếu hụt trầm trọng dưỡng chất để phát triển xương, cản trở trực tiếp đến sự tăng trưởng chiều cao.", "isEnd": true, "isSuccess": false}, "fail_unverified": {"text": "❌ Sai rồi! Sử dụng thực phẩm chức năng kích thích hormone không rõ nguồn gốc có thể gây rối loạn nội tiết tố tuổi dậy thì và dẫn đến các bệnh lý nguy hiểm.", "isEnd": true, "isSuccess": false}, "fail_heavy": {"text": "❌ Sai rồi! Tập tạ quá nặng khi xương chưa phát triển hoàn thiện dễ gây tổn thương đĩa sụn, chấn thương cột sống và kìm hãm chiều cao.", "isEnd": true, "isSuccess": false}, "fail_bone": {"text": "❌ Sai rồi! Bẻ khớp nắn xương vô học có thể dẫn đến chấn thương cột sống nghiêm trọng và rạn nứt xương vĩnh viễn.", "isEnd": true, "isSuccess": false}}}', 2),
(@ml_id, 'sorting', '{"instruction": "Hãy phân loại các biểu hiện và hành vi dậy thì sau:", "leftBox": {"title": "Tự nhiên & Bình thường"}, "rightBox": {"title": "Lầm tưởng / Có hại"}, "items": [{"text": "Cơ thể tăng cân và nở hông/vai", "correctBox": "left"}, {"text": "Uống thuốc hormone tăng chiều cao thần tốc", "correctBox": "right"}, {"text": "Cảm xúc nhạy cảm, dễ khóc dễ giận vô cớ", "correctBox": "left"}, {"text": "Nhịn ăn sáng để kìm hãm phát triển cơ thể", "correctBox": "right"}, {"text": "Vỡ giọng khàn khàn ở các bạn trai", "correctBox": "left"}, {"text": "Nịt ngực thật chặt để giấu dáng ngực nữ", "correctBox": "right"}, {"text": "Mọc lông tơ trên các vùng cơ thể", "correctBox": "left"}, {"text": "Tự bôi kem chứa testosterone mua lậu để dậy thì nhanh", "correctBox": "right"}, {"text": "Xuất hiện khí hư màu trắng trong không mùi", "correctBox": "left"}, {"text": "Nhịn gội đầu tắm rửa trong suốt kỳ hành kinh", "correctBox": "right"}]}', 3),
(@ml_id, 'matching', '{"instruction": "Ghép cặp các cột mốc dậy thì với cơ chế sinh học tương ứng:", "pairs": [{"left": "Tuyến yên", "right": "Tổng chỉ huy kích hoạt các hormone sinh dục"}, {"left": "Estrogen", "right": "Hormone điều hòa sự phát triển nữ tính"}, {"left": "Testosterone", "right": "Hormone thúc đẩy cơ bắp và vỡ giọng nam"}, {"left": "Đồng hồ sinh học", "right": "Nhịp độ dậy thì riêng biệt của mỗi cơ thể"}, {"left": "Hạch hạnh nhân", "right": "Vùng não kiểm soát cảm xúc nhạy cảm"}, {"left": "Vỏ não trước trán", "right": "Vùng não kiểm soát hành vi và suy nghĩ logic"}, {"left": "Dậy thì muộn", "right": "Chưa có dấu hiệu dậy thì sau tuổi 15-16 cần khám y khoa"}, {"left": "Áp lực đồng trang lứa", "right": "Cảm giác bồn chồn muốn thay đổi ngoại hình giống bạn bè"}]}', 4),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 1: Điền từ thích hợp về cơ chế sinh học của tuổi dậy thì:", "sentence": "Dậy thì là hành trình [blank1] tự nhiên dưới sự điều khiển của hệ nội tiết. Tuyến yên sẽ tiết ra hormone kích thích buồng trứng và tinh hoàn sản xuất [blank2] và testosterone. Những chất này đi theo dòng máu, làm thay đổi [blank3] và kích hoạt sự phát triển của xương, cơ bắp. Đừng lo lắng nếu thấy cơ thể lớn lên theo một nhịp độ [blank4] so với các bạn khác, bởi mỗi người đều có một chiếc [blank5] sinh học riêng.", "blanks": {"blank1": {"correct": "trưởng thành", "placeholder": "..."}, "blank2": {"correct": "estrogen", "placeholder": "..."}, "blank3": {"correct": "vóc dáng", "placeholder": "..."}, "blank4": {"correct": "khác biệt", "placeholder": "..."}, "blank5": {"correct": "đồng hồ", "placeholder": "..."}}, "words": ["trưởng thành", "estrogen", "vóc dáng", "khác biệt", "đồng hồ", "nhanh chóng", "bất trị", "đột biến", "giữ nguyên", "gan thận"]}', 5),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 2: Điền từ thích hợp về sự biến động cảm xúc tuổi dậy thì:", "sentence": "Ở tuổi dậy thì, sự gia tăng hormone làm tăng độ nhạy cảm của hạch [blank1], vùng não kiểm soát cảm xúc. Do đó, bạn dễ cảm thấy [blank2] hoặc tức giận vô cớ. Tuy nhiên, vỏ não trước trán chịu trách nhiệm [blank3] hành vi vẫn đang trong quá trình hoàn thiện. Để kiểm soát cảm xúc, hãy học cách dừng lại, [blank4] sâu và đặt tên cho cảm giác của mình. Bố mẹ và thầy cô chính là [blank5] tin cậy giúp bạn định hướng hành vi.", "blanks": {"blank1": {"correct": "hạnh nhân", "placeholder": "..."}, "blank2": {"correct": "nhạy cảm", "placeholder": "..."}, "blank3": {"correct": "kiểm soát", "placeholder": "..."}, "blank4": {"correct": "hít thở", "placeholder": "..."}, "blank5": {"correct": "điểm tựa", "placeholder": "..."}}, "words": ["hạnh nhân", "nhạy cảm", "kiểm soát", "hít thở", "điểm tựa", "vỏ não", "vui vẻ", "kìm nén", "trốn chạy", "đồng phạm"]}', 6),
(@ml_id, 'interaction', '{"question": "Khi nhận thấy mình dậy thì muộn hơn các bạn cùng lớp rất nhiều, hành động nào là đúng đắn và an toàn nhất?", "choices": [{"text": "Kiên nhẫn theo dõi, duy trì lối sống lành mạnh và đi khám bác sĩ nội tiết nếu sau 15-16 tuổi vẫn chưa có dấu hiệu dậy thì.", "correct": true, "emoji": "💚"}, {"text": "Tự ý mua các loại kem bôi hoặc thuốc uống chứa hormone sinh dục ngoài tiệm thuốc để kích thích cơ thể dậy thì nhanh hơn.", "correct": false, "emoji": "🛑"}]}', 7),
(@ml_id, 'interaction', '{"question": "Bạn có cảm xúc giận dữ bộc phát và cãi nhau với bố mẹ chỉ vì một việc nhỏ. Cách xoa dịu vùng hạch hạnh nhân hiệu quả nhất lúc này là gì?", "choices": [{"text": "Dừng lại, hít thở sâu 3 nhịp, gọi tên cảm xúc (\"mình đang giận\") để vỏ não trước trán kích hoạt kiểm soát.", "correct": true, "emoji": "💚"}, {"text": "Đóng sập cửa phòng, viết status tức tối bêu riếu bố mẹ trên mạng xã hội để giải tỏa năng lượng tiêu cực.", "correct": false, "emoji": "🛑"}]}', 8),
(@ml_id, 'interaction', '{"question": "Hormone sinh dục tăng vọt ở tuổi dậy thì thực chất có vai trò như thế nào đối với tâm trạng của học sinh?", "choices": [{"text": "Chúng kích hoạt vùng não cảm xúc làm tăng độ nhạy cảm tự nhiên, không phải do bạn \"hư hỏng\" hay \"bất trị\".", "correct": true, "emoji": "💚"}, {"text": "Chúng trực tiếp điều khiển khiến bạn trở nên độc ác, nổi loạn và thích gây gổ với mọi người xung quanh.", "correct": false, "emoji": "🛑"}]}', 9),
(@ml_id, 'interaction', '{"question": "Nếu thấy bạn bè trong lớp phát triển nhanh hơn hẳn về vóc dáng và chiều cao, thái độ nào là thông thái nhất?", "choices": [{"text": "Chấp nhận nhịp độ sinh học riêng biệt của bản thân, không so sánh và tập trung rèn luyện cơ thể.", "correct": true, "emoji": "💚"}, {"text": "Nhịn ăn sáng và mua thuốc bôi kích thích hormone để đuổi kịp tốc độ của các bạn.", "correct": false, "emoji": "🛑"}]}', 10),
(@ml_id, 'interaction', '{"question": "Vùng não nào đóng vai trò ''tổng phanh'' kiểm soát hành vi bốc đồng nhưng lại hoàn thiện muộn nhất ở tuổi dậy thì?", "choices": [{"text": "Vỏ não trước trán.", "correct": true, "emoji": "💚"}, {"text": "Hạch hạnh nhân.", "correct": false, "emoji": "🛑"}]}', 11);
INSERT INTO lessons (course_id, slug, title, summary, content, lesson_order, is_free, xp_reward, estimated_minutes)
INSERT INTO lesson_sources (lesson_id, source_name, source_url, source_type) VALUES
(@lesson2_id, 'Scarleteen - Not Everything You Wanted To Know About Puberty', 'https://www.scarleteen.com/read/bodies/not-everything-you-wanted-know-about-puberty-pretty-darn-close', 'website');
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson2_id, 'Chiều cao và cân nặng', 1);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có nhận ra đôi giày thể thao yêu thích bỗng chốc trở nên chật ních chỉ sau một kỳ nghỉ hè?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Tuổi dậy thì chứng kiến đợt bứt phá chiều cao (growth spurt) lớn thứ hai trong đời, chỉ sau giai đoạn sơ sinh.", "Xương tay, xương chân kéo dài nhanh chóng, đi kèm với sự phát triển của các nhóm cơ và sự phân bố lại lượng mỡ cơ thể.", "Vóc dáng của bạn thay đổi rõ rệt để chuẩn bị cho cơ thể của người trưởng thành."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống tăng cân", "body": "Trang thấy rất hoang mang khi cân nặng tăng vọt 4kg trong vòng nửa năm, trong khi vùng hông và đùi trở nên tròn trịa hơn. Trang lo sợ mình đang bị béo phì và định nhịn ăn tinh bột."}', 3),
(@ml_id, 'interaction', '{"question": "Trang nên nhìn nhận sự thay đổi cân nặng này như thế nào?", "choices": [{"text": "Đây là sự phân bố mỡ tự nhiên ở nữ giới để phát triển các cơ quan sinh sản bình thường.", "correct": true, "emoji": "💚"}, {"text": "Cân nặng tăng là dấu hiệu xấu, cần phải ăn kiêng khắt khe ngay để giữ dáng thon thả.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có thấy cơ thể mình thay đổi hình dáng rõ rệt nhất ở bộ phận nào gần đây?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Tăng cân và nở hông/vai là dấu hiệu cơ thể bạn đang tích lũy năng lượng để trưởng thành."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson2_id, 'Làn da ẩm ương và mùi cơ thể', 2);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có từng giật mình khi thấy một nốt mụn đỏ lòm xuất hiện ngay giữa trán trước ngày chụp ảnh lớp?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Các hormone dậy thì kích thích tuyến bã nhờn (sebaceous glands) hoạt động mạnh mẽ, làm da mặt dễ bị dầu và bít tắc lỗ chân lông gây mụn.", "Đồng thời, các tuyến mồ hôi hoạt động mạnh hơn, kết hợp với vi khuẩn trên da tạo nên mùi cơ thể đặc trưng.", "Đây là những hiện tượng sinh lý hết sức bình thường và hoàn toàn có thể quản lý được bằng vệ sinh đúng cách."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống tự ti", "body": "Huy thấy nách mình ra nhiều mồ hôi và có mùi khó chịu sau mỗi tiết thể dục. Huy xấu hổ, không dám giơ tay phát biểu hay đứng gần các bạn vì sợ bị phát hiện mùi."}', 3),
(@ml_id, 'interaction', '{"question": "Huy nên xử lý tình huống mùi cơ thể này như thế nào để tự tin hơn?", "choices": [{"text": "Tắm rửa sạch sẽ hàng ngày, sử dụng lăn khử mùi sau khi tắm và mặc áo cotton thông thoáng.", "correct": true, "emoji": "💚"}, {"text": "Dùng nước hoa thật đậm xịt đè lên vùng mồ hôi nách để lấp liếm mùi khó chịu.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã xây dựng thói quen chăm sóc da mặt và cơ thể của mình như thế nào để đối phó với mụn và mồ hôi?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Mụn hay mùi cơ thể chỉ là những lag nhẹ của hệ thống sinh học, dọn dẹp sạch sẽ là ổn ngay!"]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson2_id, 'Sự ngại ngùng và so sánh ngoại hình', 3);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Có bao giờ bạn muốn giấu mình trong những chiếc áo hoodie rộng thùng lình để không ai nhìn thấy cơ thể mình thay đổi?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Sự phát triển của ngực ở nữ hay vỡ giọng, mọc lông ở nam thường đi kèm với cảm giác ngượng ngùng, lúng túng.", "Bạn bắt đầu ý thức cực kỳ rõ về việc cơ thể mình trông như thế nào trong mắt người khác.", "So sánh sự phát triển của mình với các bạn xung quanh hoặc các hình mẫu trên mạng chỉ làm tăng thêm lo âu vô ích."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống giấu dáng", "body": "Vy bắt đầu phát triển ngực và cảm thấy vô cùng bối rối khi vòng một nhô lên rõ rệt dưới lớp áo đồng phục. Vy luôn khom lưng khi đi lại và mặc thêm áo khoác dày cộp dù trời nóng bức để che giấu."}', 3),
(@ml_id, 'interaction', '{"question": "Vy nên làm gì để cảm thấy thoải mái và tự tin hơn với sự phát triển này?", "choices": [{"text": "Trò chuyện với mẹ để chọn mua loại áo lá hoặc áo ngực học sinh mềm mại, vừa vặn để nâng đỡ nhẹ nhàng.", "correct": true, "emoji": "💚"}, {"text": "Tiếp tục khom lưng giấu dáng vì nghĩ đây là chuyện xấu hổ, không nên cho ai biết.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có từng cảm thấy ngượng ngùng vì một thay đổi thể chất nào đó trên cơ thể mình chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Thay đổi cơ thể là huy hiệu của sự trưởng thành, không phải là điều cần che giấu."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson2_id, 'Biến đổi sinh dục ngoài', 4);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có lo lắng khi nhận ra những sợi lông mảnh dẻ bắt đầu xuất hiện ở những vùng nhạy cảm trên cơ thể?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Mọc lông mu (vùng kín) và lông nách là một trong những cột mốc phát triển sinh dục ngoài quan trọng ở cả hai giới.", "Lông vùng nhạy cảm đóng vai trò bảo vệ da, giảm ma sát và ngăn ngừa vi khuẩn xâm nhập vào cơ quan sinh dục.", "Màu sắc, độ rậm rạp của lông phụ thuộc vào gen di truyền và hoàn toàn bình thường cho dù có khác biệt với người khác."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống hoang mang", "body": "Minh thấy vùng kín của mình bắt đầu mọc lông rậm rạp và sẫm màu. Minh lo sợ mình bị biến đổi dị thường vì các bạn trong nhóm chưa ai kể về chuyện này."}', 3),
(@ml_id, 'interaction', '{"question": "Minh nên hiểu về sự phát triển lông cơ thể này như thế nào?", "choices": [{"text": "Đây là hiện tượng sinh lý hoàn toàn bình thường báo hiệu hệ sinh dục ngoài đang hoàn thiện.", "correct": true, "emoji": "💚"}, {"text": "Chắc chắn do mình bị rối loạn hormone rồi, phải tìm cách cạo sạch ngay lập tức để trông sạch sẽ.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có biết cách giữ vệ sinh và chăm sóc các vùng nhạy cảm khi lông cơ thể bắt đầu phát triển không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Mỗi sợi lông mọc lên đều mang nhiệm vụ bảo vệ cơ thể bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson2_id, 'Cơn vỡ giọng và giấc mơ ướt', 5);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có từng giật mình vì giọng nói của mình bỗng khàn đặc như vịt đực hay thức dậy với một bãi ướt trên quần?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Ở nam giới, testosterone làm thanh quản rộng ra và dây thanh đới dày lên, gây ra hiện tượng vỡ giọng (voice cracking).", "Đồng thời, tinh hoàn bắt đầu sản xuất tinh trùng. Hiện tượng xuất tinh tự nhiên ban đêm khi ngủ được gọi là mộng tinh (wet dream).", "Cả vỡ giọng và mộng tinh đều là những dấu hiệu tự nhiên cho thấy cơ quan sinh sản nam đang hoạt động khỏe mạnh."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống ngượng ngùng", "body": "Hoàng thức dậy và phát hiện quần lót mình bị ướt và dính nhớp một chất dịch màu trắng đục. Hoàng vô cùng lo sợ, nghĩ rằng mình đã làm chuyện bậy bạ hoặc bị bệnh nam khoa nặng."}', 3),
(@ml_id, 'interaction', '{"question": "Hoàng nên ứng phó với tình huống mộng tinh này như thế nào?", "choices": [{"text": "Thay quần lót sạch, giặt ga trải giường, tự nhủ: ''Đây là mộng tinh tự nhiên, cơ thể mình đang sản xuất tinh dịch bình thường''.", "correct": true, "emoji": "💚"}, {"text": "Giấu nhẹm chiếc quần bẩn vào góc tủ vì xấu hổ và tự dằn vặt bản thân là kẻ biến thái đầu óc đen tối.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã chuẩn bị tâm lý thế nào cho những thay đổi sinh lý đặc trưng của giới tính mình chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Mộng tinh là cơ chế tự giải phóng tinh dịch dư thừa của cơ thể nam giới khỏe mạnh."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson2_id, 'Trân trọng cơ thể thay đổi', 6);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có sẵn lòng ký hiệp ước hòa bình với những thay đổi thể chất đang diễn ra trên cơ thể mình?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Quá trình dậy thì có thể khiến cơ thể bạn tạm thời mất cân đối (tay chân quá dài, da nhiều dầu, giọng khàn).", "Đây chỉ là giai đoạn đệm trước khi cơ thể đạt được trạng thái hài hòa, ổn định của người trưởng thành.", "Học cách trân trọng chức năng hoạt động của cơ thể thay vì chỉ săm soi khuyết điểm ngoại hình giúp bạn tự tin hơn."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống tự ti", "body": "Lan cảm thấy ghét đôi chân dài ngoằng khòng khoeo của mình và luôn mặc quần ống rộng quét đất để che giấu. Lan nghĩ cơ thể mình thật kỳ dị và xấu xí."}', 3),
(@ml_id, 'interaction', '{"question": "Lan nên viết lại suy nghĩ tự ti của mình như thế nào để cảm thấy bao dung hơn với bản thân?", "choices": [{"text": "Đôi chân dài giúp mình đi lại nhanh nhẹn, đạp xe và giúp mình cao ráo hơn. Cơ thể đang nỗ lực lớn lên, mình cần kiên nhẫn.", "correct": true, "emoji": "💚"}, {"text": "Mình phải tìm cách đi giày cao gót hoặc mặc đồ bó sát để ép cơ thể trông cân đối hơn bằng mọi giá.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Một thay đổi cơ thể nào gần đây khiến bạn thấy lúng túng nhất? Bạn có thể chấp nhận nó thế nào?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Cơ thể bạn không phải là một món đồ trang trí, đó là phương tiện giúp bạn khám phá thế giới."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson2_id, 'Bài kiểm tra: Thử thách tổng kết', 99);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Chào mừng bạn đến với Thử thách Tổng kết bài học ''Những biến đổi lớn trên cơ thể''! Hãy kiểm tra kiến thức về giọng nói, mùi cơ thể và các tuyến tiết sinh lý nhé."}', 1),
(@ml_id, 'scenario-choice', '{"title": "Chăm sóc cơ thể khi vỡ giọng và mọc lông", "startNode": "step1", "nodes": {"step1": {"text": "Đức bị vỡ giọng khàn khàn, bạn bè trêu chọc Đức phát ra âm thanh giống vịt đực. Đức thấy vô cùng tự ti và muốn làm giọng mình trong trẻo trở lại.", "choices": [{"text": "Cố gắng nhịn nói chuyện tối đa, giả vờ đau họng để không phải phát biểu.", "nextNode": "fail_silent"}, {"text": "Chấp nhận đây là hiện tượng sinh lý tự nhiên, nói chuyện với âm lượng vừa phải và uống nước ấm.", "nextNode": "step2"}]}, "step2": {"text": "Một bạn mách Đức nên uống các loại nước lá thảo mộc truyền miệng tự chế ở nhà để chữa khản tiếng nhanh chóng.", "choices": [{"text": "Tự mua các loại lá thảo mộc không rõ nguồn gốc về đun uống bừa bãi.", "nextNode": "fail_herbs"}, {"text": "Tìm hiểu khoa học, nhận thấy vỡ giọng do dây thanh âm dày lên dưới tác động của hormone nam, không thể chữa bằng mẹo nam y.", "nextNode": "step3"}]}, "step3": {"text": "Đức phát hiện cơ thể bắt đầu mọc lông mu và lông nách dày hơn. Đức cảm thấy ngứa ngáy và muốn dùng dao cạo râu cũ của bố để cạo sạch chúng.", "choices": [{"text": "Dùng dao cạo cũ cạo khô lông nách và lông mu để sạch sẽ nhanh chóng.", "nextNode": "fail_shave"}, {"text": "Giữ vệ sinh sạch sẽ bằng nước ấm, chỉ dùng kéo sạch cắt tỉa gọn gàng nếu quá ngứa ngáy, tránh cạo sát da.", "nextNode": "step4"}]}, "step4": {"text": "Đức phát hiện nách bắt đầu đổ nhiều mồ hôi và phát ra mùi hôi chua sau mỗi lần tập bóng rổ. Bạn mách Đức dùng cồn y tế lau nách để diệt khuẩn triệt để.", "choices": [{"text": "Bôi cồn y tế 90 độ trực tiếp lên nách để sát trùng mạnh.", "nextNode": "fail_alcohol"}, {"text": "Tắm rửa xà phòng trung tính, lau khô và dùng sản phẩm lăn nách dịu nhẹ.", "nextNode": "step5"}]}, "step5": {"text": "Sau một đêm ngủ dậy, Đức thấy quần lót và ga giường có vệt dịch ẩm ướt kèm mùi lạ. Đức sợ hãi nghĩ mình bị bệnh thận bẩm sinh.", "choices": [{"text": "Bình tĩnh nhận diện đây là hiện tượng mộng tinh bình thường, đem ga giường đi giặt sạch sẽ.", "nextNode": "success_end"}, {"text": "Giấu chăn gối đi, âm thầm uống các loại thực phẩm chức năng bổ thận tráng dương tự mua.", "nextNode": "fail_kidney"}]}, "success_end": {"text": "🎉 Hoàn thành xuất sắc! Bạn đã biết cách bảo vệ dây thanh âm đúng khoa học, xử lý lông cơ thể và vệ sinh mồ hôi, mộng tinh an toàn.", "isEnd": true, "isSuccess": true}, "fail_silent": {"text": "❌ Chưa đúng! Nhịn nói không giúp dây thanh âm nhỏ lại mà chỉ làm bạn tự cô lập bản thân và mất đi sự tự tin giao tiếp.", "isEnd": true, "isSuccess": false}, "fail_herbs": {"text": "❌ Chưa đúng! Các bài thuốc truyền miệng tự chế không rõ liều lượng có thể gây dị ứng hoặc nhiễm khuẩn, làm viêm thanh quản nặng thêm.", "isEnd": true, "isSuccess": false}, "fail_shave": {"text": "❌ Sai rồi! Cạo lông bằng dao cạo cũ bẩn dễ gây trầy xước da, dẫn đến viêm nang lông và lông mọc ngược đau rát.", "isEnd": true, "isSuccess": false}, "fail_alcohol": {"text": "❌ Sai rồi! Cồn nồng độ cao làm khô da nghiêm trọng, gây bỏng rát và tăng tiết mồ hôi bù trừ nặng hơn ở vùng nách.", "isEnd": true, "isSuccess": false}, "fail_kidney": {"text": "❌ Sai rồi! Mộng tinh là hiện tượng sinh lý giải phóng tinh trùng thừa tự nhiên, tự uống thuốc bổ thận khi dậy thì cực kỳ hại gan.", "isEnd": true, "isSuccess": false}}}', 2),
(@ml_id, 'sorting', '{"instruction": "Hãy phân loại các phương pháp chăm sóc cơ thể dậy thì sau:", "leftBox": {"title": "Chăm sóc an toàn"}, "rightBox": {"title": "Có hại / Phản khoa học"}, "items": [{"text": "Uống nước ấm và hạn chế hét to khi vỡ giọng", "correctBox": "left"}, {"text": "Tự cạo khô lông nách bằng dao cạo râu cũ", "correctBox": "right"}, {"text": "Dùng kéo sạch tỉa bớt lông mu nếu quá ngứa", "correctBox": "left"}, {"text": "Uống nước thảo mộc tự đun để chữa vỡ giọng", "correctBox": "right"}, {"text": "Mặc quần lót chất liệu cotton thoáng mát", "correctBox": "left"}, {"text": "Giấu kín không thay ga giường sau khi mộng tinh", "correctBox": "right"}, {"text": "Tắm rửa xà phòng dịu nhẹ sau khi tập thể thao", "correctBox": "left"}, {"text": "Bôi cồn 90 độ lên nách để khử trùng mồ hôi", "correctBox": "right"}, {"text": "Giặt đồ lót và phơi dưới ánh nắng mặt trời", "correctBox": "left"}, {"text": "Uống thuốc bổ thận tự mua để chữa mộng tinh", "correctBox": "right"}]}', 3),
(@ml_id, 'matching', '{"instruction": "Ghép cặp các biến đổi cơ thể với cách chăm sóc tương ứng:", "pairs": [{"left": "Vỡ giọng", "right": "Hiện tượng dây thanh âm dày và dài ra ở bạn trai"}, {"left": "Lông cơ thể", "right": "Lớp rào chắn bảo vệ da khỏi cọ xát và vi khuẩn"}, {"left": "Viêm nang lông", "right": "Nguy cơ khi cạo lông không đúng cách bằng dao cạo bẩn"}, {"left": "Mộng tinh", "right": "Cơ chế tự giải phóng tinh dịch thừa khi ngủ ở nam"}, {"left": "Tắm rửa hàng ngày", "right": "Biện pháp làm sạch chất nhờn và mồ hôi dậy thì"}, {"left": "Giặt ga trải giường", "right": "Hành động vệ sinh cần làm ngay sau khi mộng tinh"}, {"left": "Bao quy đầu", "right": "Nơi bám bẩn bựa sinh dục cần kéo nhẹ để rửa sạch"}, {"left": "Dây thanh âm", "right": "Cơ quan phát âm cần tránh la hét quá to khi đang vỡ giọng"}]}', 4),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 1: Điền từ thích hợp về sự biến đổi thanh âm và cách chăm sóc:", "sentence": "Hiện tượng vỡ giọng xảy ra khi hormone nam thúc đẩy dây thanh âm [blank1] và dài ra. Tiếng nói của bạn trai sẽ trở nên [blank2] và đôi lúc bị hụt hơi. Đây là một sự chuyển đổi sinh lý [blank3], không phải là bệnh lý nên không cần dùng các loại nước lá [blank4] không rõ nguồn gốc. Hãy bảo vệ giọng nói bằng cách uống [blank5] ấm và hạn chế la hét quá lớn.", "blanks": {"blank1": {"correct": "dày lên", "placeholder": "..."}, "blank2": {"correct": "trầm khàn", "placeholder": "..."}, "blank3": {"correct": "tự nhiên", "placeholder": "..."}, "blank4": {"correct": "truyền miệng", "placeholder": "..."}, "blank5": {"correct": "nước", "placeholder": "..."}}, "words": ["dày lên", "trầm khàn", "tự nhiên", "truyền miệng", "nước", "mỏng đi", "trong trẻo", "đột ngột", "tự chế", "nước đá"]}', 5),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 2: Điền từ thích hợp về sự phát triển tuyến mồ hôi và lông cơ thể:", "sentence": "Tuyến mồ hôi và bã nhờn hoạt động mạnh dễ gây ra [blank1] cơ thể dậy thì. Để vệ sinh sạch sẽ, bạn nên tắm rửa hàng ngày và mặc quần lót [blank2] thoáng khí. Sự xuất hiện của lông mu giúp giảm [blank3] và bảo vệ niêm mạc nhạy cảm. Ngoài ra, hiện tượng [blank4] là cơ chế tự giải phóng tinh dịch thừa của bạn trai khi ngủ. Hãy chủ động [blank5] ga giường và quần lót sạch sau khi gặp hiện tượng này.", "blanks": {"blank1": {"correct": "mùi", "placeholder": "..."}, "blank2": {"correct": "cotton", "placeholder": "..."}, "blank3": {"correct": "cọ xát", "placeholder": "..."}, "blank4": {"correct": "mộng tinh", "placeholder": "..."}, "blank5": {"correct": "thay giặt", "placeholder": "..."}}, "words": ["mùi", "cotton", "cọ xát", "mộng tinh", "thay giặt", "mụn", "nilon", "ngứa ngáy", "di tinh", "giấu kín"]}', 6),
(@ml_id, 'interaction', '{"question": "Khi bạn trai thức dậy phát hiện ga giường bị vấy bẩn do mộng tinh lần đầu, hành động nào là đúng đắn và văn minh nhất?", "choices": [{"text": "Bình tĩnh thay quần lót mới, đem ga giường đi giặt sạch sẽ và hiểu rằng đây là hiện tượng sinh lý bình thường.", "correct": true, "emoji": "💚"}, {"text": "Hoảng sợ lo lắng nghĩ mình bị bệnh thận, âm thầm úp chăn lên vệt bẩn để giấu bố mẹ vì xấu hổ.", "correct": false, "emoji": "🛑"}]}', 7),
(@ml_id, 'interaction', '{"question": "Hành động nào sau đây giúp hạn chế tối đa nguy cơ viêm thanh quản trong giai đoạn bạn trai đang vỡ giọng?", "choices": [{"text": "Hạn chế la hét quá lớn, uống đủ nước ấm và tránh uống nước đá quá lạnh liên tục.", "correct": true, "emoji": "💚"}, {"text": "Tập luyện nói giọng trầm cố ép giọng để nghe nam tính hơn từ sớm.", "correct": false, "emoji": "🛑"}]}', 8),
(@ml_id, 'interaction', '{"question": "Tại sao việc dùng kéo cắt tỉa lông vùng kín lại an toàn hơn việc dùng dao cạo sát da?", "choices": [{"text": "Vì cạo sát da dễ làm tổn thương lớp biểu bì nhạy cảm, gây trầy xước và viêm nang lông vùng nhạy cảm.", "correct": true, "emoji": "💚"}, {"text": "Vì lông vùng kín có chức năng giữ nhiệt nên cạo sạch sẽ làm cơ thể bị nhiễm lạnh.", "correct": false, "emoji": "🛑"}]}', 9),
(@ml_id, 'interaction', '{"question": "Bản chất sinh học của hiện tượng mộng tinh ở bạn trai dậy thì là gì?", "choices": [{"text": "Cơ chế tự đào thải tự nhiên của cơ thể để giải phóng lượng tinh dịch dư thừa khi nằm ngủ.", "correct": true, "emoji": "💚"}, {"text": "Hiện tượng cơ thể bị thiếu hụt hormone nam trầm trọng dẫn đến rò rỉ tinh chất.", "correct": false, "emoji": "🛑"}]}', 10),
(@ml_id, 'interaction', '{"question": "Mùi chua nồng nặc ở vùng nách tuổi dậy thì chủ yếu do nguyên nhân nào gây ra?", "choices": [{"text": "Mồ hôi từ tuyến đầu hủy (apocrine) tương tác với vi khuẩn cư trú trên bề mặt da.", "correct": true, "emoji": "💚"}, {"text": "Độc tố tích tụ từ gan thải ra trực tiếp qua da nách do ăn quá nhiều đồ cay nóng.", "correct": false, "emoji": "🛑"}]}', 11);
INSERT INTO lessons (course_id, slug, title, summary, content, lesson_order, is_free, xp_reward, estimated_minutes)
INSERT INTO lesson_sources (lesson_id, source_name, source_url, source_type) VALUES
(@lesson3_id, 'Scarleteen - Quickies: Sexual Anatomy', 'https://www.scarleteen.com/read/bodies/quickies-sexual-anatomy', 'website');
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson3_id, 'Cơ quan sinh sản là gì?', 1);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có từng cảm thấy ngượng ngùng khi nghe ai đó nhắc đến những từ như âm đạo hay tinh hoàn?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Cơ quan sinh sản (reproductive system) là một phần tự nhiên của giải phẫu cơ thể người, có chức năng duy trì nòi giống và cảm nhận khoái cảm.", "Sử dụng đúng thuật ngữ khoa học (như dương vật, âm hộ, tử cung) giúp chúng ta giao tiếp văn minh, rõ ràng về sức khỏe.", "Không có bộ phận nào trên cơ thể là dơ bẩn hay xấu hổ; tất cả đều có cấu tạo và nhiệm vụ sinh học quý giá."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống ngượng ngùng", "body": "Trong giờ Sinh học, thầy giáo giảng về cấu tạo cơ quan sinh dục. Cả lớp bỗng xầm xì, khúc khích cười và cúi gầm mặt xuống bàn vì thấy đỏ mặt ngại ngùng."}', 3),
(@ml_id, 'interaction', '{"question": "Thái độ đúng đắn và văn minh nhất của bạn trong giờ học này là gì?", "choices": [{"text": "Lắng nghe nghiêm túc, ghi chép khoa học vì đây là kiến thức y sinh học cơ bản cần biết để bảo vệ sức khỏe.", "correct": true, "emoji": "💚"}, {"text": "Cười đùa hùa theo các bạn hoặc lấy điện thoại ra nhắn tin đùa cợt thô tục về các bộ phận nhạy cảm.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có cảm thấy thoải mái khi sử dụng các thuật ngữ giải phẫu khoa học để nói về sức khỏe của mình không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Gọi tên đúng các bộ phận là bước đầu tiên để chăm sóc sức khỏe khoa học."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson3_id, 'Cấu tạo sinh học nữ', 2);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có biết âm hộ và âm đạo thực ra là hai bộ phận hoàn toàn khác nhau của cơ thể nữ giới?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["**Âm hộ (vulva)** là toàn bộ cơ quan sinh dục ngoài có thể nhìn thấy, bao gồm môi lớn, môi bé và âm vật (clitoris - cơ quan nhạy cảm chứa nhiều đầu dây thần kinh).", "**Âm đạo (vagina)** là ống cơ co giãn dẫn từ âm hộ vào tử cung bên trong cơ thể, nơi máu kinh nguyệt thoát ra ngoài.", "Hiểu đúng cấu tạo giúp bạn gái biết cách vệ sinh và chăm sóc cơ thể an toàn."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống hoang mang", "body": "Vy muốn thử dùng cốc nguyệt san hoặc tampon nhưng lo sợ nó sẽ bị tụt sâu vào tận ổ bụng và biến mất vĩnh viễn vì âm đạo quá sâu."}', 3),
(@ml_id, 'interaction', '{"question": "Vy nên hiểu cấu tạo âm đạo như thế nào để bớt lo lắng?", "choices": [{"text": "Âm đạo là một đường ống khép kín ở phía cuối, được ngăn cách với tử cung bằng cổ tử cung nhỏ hẹp, nên đồ vật không thể đi sâu vào ổ bụng.", "correct": true, "emoji": "💚"}, {"text": "Âm đạo thông thẳng vào toàn bộ cơ thể bên trong, nên tuyệt đối không được đưa bất cứ vật gì vào.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã bao giờ tự tìm hiểu về cấu tạo sinh học của cơ thể mình qua các nguồn thông tin y khoa chính thống chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Hiểu biết về cơ thể giúp bạn đưa ra những quyết định chăm sóc sức khỏe thông thái."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson3_id, 'Cấu tạo sinh học nam', 3);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có biết dương vật và tinh hoàn của nam giới hoạt động như một nhà máy sản xuất tự động 24/7?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["**Dương vật (penis)** gồm thân dương vật và quy đầu nhạy cảm, chứa các mô xốp có thể cương cứng khi có kích thích hoặc tự động cương vào buổi sáng.", "**Tinh hoàn (testicles)** nằm trong bìu, đóng vai trò sản xuất tinh trùng và hormone testosterone.", "Bao quy đầu (foreskin) là lớp da bảo vệ đầu dương vật, cần được chú ý vệ sinh sạch sẽ mỗi ngày."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống bối rối", "body": "Khang thức dậy chuẩn bị đi học thì thấy dương vật của mình tự nhiên cương cứng ngắc mà không hề có suy nghĩ nhạy cảm nào. Khang thấy vô cùng ngượng và sợ bị phát hiện."}', 3),
(@ml_id, 'interaction', '{"question": "Khang nên nhìn nhận hiện tượng cương cứng buổi sáng này như thế nào?", "choices": [{"text": "Đây là hiện tượng cương cứng tự nhiên", "correct": true, "emoji": "💚"}, {"text": "Chắc chắn do đầu óc mình có vấn đề đen tối nên cơ thể mới phản ứng như vậy, cần tự kiểm điểm bản thân.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có biết cách làm vệ sinh bao quy đầu đúng cách khi tắm rửa hàng ngày không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Cương cứng tự nhiên là tín hiệu hệ mạch máu và thần kinh nam giới đang hoạt động tốt."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson3_id, 'Sự tò mò và tự khám phá', 4);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Có phải việc tò mò khám phá cơ thể của chính mình là hành vi dơ bẩn hay có lỗi?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Sự tò mò về cơ thể và cảm giác nhạy cảm ở vùng kín là phản ứng sinh học hoàn toàn tự nhiên khi hormone dậy thì dâng cao.", "Tự kích thích hay tự khám phá cơ thể (masturbation) là hành vi riêng tư phổ biến, giúp giải tỏa áp lực sinh lý và hiểu rõ phản xạ cơ thể.", "Hành vi này chỉ không lành mạnh nếu nó gây nghiện, ảnh hưởng đến học tập hoặc diễn ra ở nơi công cộng xâm phạm ranh giới người khác."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống tội lỗi", "body": "Huy lỡ tay chạm vào vùng kín và thấy có cảm giác dễ chịu. Sau đó Huy vô cùng hoảng sợ và dằn vặt, nghĩ rằng mình là kẻ tội lỗi, đồi trụy và sẽ bị suy giảm trí nhớ."}', 3),
(@ml_id, 'interaction', '{"question": "Huy nên hiểu đúng về cảm xúc tội lỗi của mình như thế nào?", "choices": [{"text": "Khám phá cơ thể là bình thường, không gây hại sức khỏe nếu giữ vệ sinh và thực hiện ở không gian riêng tư.", "correct": true, "emoji": "💚"}, {"text": "Lời đồn là đúng, tự khám phá sẽ hủy hoại tương lai nên phải tự trừng phạt bản thân để chừa.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã bao giờ nghe những tin đồn đáng sợ nào về việc tự khám phá cơ thể chưa? Bạn đối phó với nó thế nào?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Cơ thể là của bạn, tìm hiểu nó một cách tôn trọng và an toàn là quyền của bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson3_id, 'Ranh giới đụng chạm', 5);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để bảo vệ vùng nhạy cảm của mình trước những đụng chạm không mong muốn từ người khác?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Quy tắc đồ bơi (swimsuit rule) chỉ ra rằng bất kỳ ai cũng không được phép đụng chạm vào vùng cơ thể được che bởi đồ bơi của bạn.", "Cơ thể bạn thuộc quyền sở hữu của riêng bạn. Bạn có quyền từ chối bất kỳ đụng chạm nào khiến bạn thấy uncomfy hay sợ hãi.", "Hãy tin vào linh cảm cơ thể (gut feeling) - nếu thấy có cờ đỏ, hãy lên tiếng hoặc rời đi ngay lập tức."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống nhạy cảm", "body": "Trong chuyến xe bus đông đúc, một người đàn ông lạ cố tình đứng sát và để tay chạm vào vùng mông của Hân. Hân thấy sợ hãi, run rẩy và đông cứng người, không dám phản kháng vì sợ mọi người nhìn."}', 3),
(@ml_id, 'interaction', '{"question": "Hân nên phản xạ nhanh như thế nào để bảo vệ bản thân trong tình huống này?", "choices": [{"text": "Tránh ra chỗ khác ngay lập tức, hoặc nói to: ''Chú tránh xa cháu ra!'' để thu hút sự chú ý của mọi người xung quanh giúp đỡ.", "correct": true, "emoji": "💚"}, {"text": "Im lặng chịu đựng, cố nhắm mắt cho qua vì nghĩ chắc họ chỉ vô tình đụng phải do xe bus đông.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã bao giờ rơi vào tình huống bị đụng chạm khiến bạn thấy khó chịu chưa? Bạn đã phản ứng thế nào?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Cơ thể bạn là thánh địa của riêng bạn, bạn có toàn quyền nói ''Không''."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson3_id, 'Tự nhận thức và tôn trọng cơ thể', 6);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có sẵn lòng hứa sẽ luôn trân trọng và bảo vệ cơ thể độc nhất vô nhị của mình không?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Tôn trọng cơ thể (body respect) là nền tảng của sự tự tin và sức khỏe tinh thần vững chắc.", "Điều này bao gồm việc chăm sóc vệ sinh, ăn uống đủ chất, nghỉ ngơi khoa học và không cho phép ai xâm phạm ranh giới cá nhân.", "Khi bạn trân trọng cơ thể mình, bạn cũng sẽ biết cách tôn trọng cơ thể và ranh giới của bạn bè xung quanh."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống đùa cợt", "body": "Nhóm bạn thân rủ nhau đùa nghịch, kéo quần hoặc đụng chạm vùng kín của một bạn nam khác trong lớp để làm trò đùa tiêu khiển. Bạn nam kia tỏ rõ sự khó chịu nhưng nhóm bạn vẫn cười hùa vui vẻ."}', 3),
(@ml_id, 'interaction', '{"question": "Hành động đùa nghịch đụng chạm nhạy cảm của nhóm bạn nên được nhìn nhận thế nào?", "choices": [{"text": "Đây là hành vi xâm hại ranh giới cơ thể nghiêm trọng dưới danh nghĩa trò đùa, cần lên tiếng ngăn chặn ngay.", "correct": true, "emoji": "💚"}, {"text": "Chỉ là đùa giỡn tuổi học trò cho vui thôi, bạn nam kia nhạy cảm quá đà mới thấy khó chịu.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã từng lên tiếng bảo vệ ranh giới cơ thể của mình hoặc của bạn bè khi bị đùa cợt khiếm nhã chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Tôn trọng cơ thể người khác cũng quan trọng như việc bảo vệ cơ thể của chính mình."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson3_id, 'Bài kiểm tra: Thử thách tổng kết', 99);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Chào mừng bạn đến với Thử thách Tổng kết bài học ''Giải phẫu cơ thể & Sự tự nhận thức''! Cùng củng cố kiến thức bảo vệ hệ sinh dục và tôn trọng ranh giới cơ thể."}', 1),
(@ml_id, 'scenario-choice', '{"title": "Bảo vệ tinh hoàn và ứng phó cương cứng bất ngờ", "startNode": "step1", "nodes": {"step1": {"text": "Nam phát hiện vùng tinh hoàn của mình bị đau tức nhẹ sau một trận va chạm bóng đá ở trường. Nam thấy rất ngượng ngùng và lo lắng.", "choices": [{"text": "Giấu kín vì xấu hổ, tự ra tiệm thuốc tây mua thuốc giảm đau liều mạnh về tự uống.", "nextNode": "fail_silent"}, {"text": "Bình tĩnh tự kiểm tra vùng bìu tinh hoàn xem có sưng đỏ không và chia sẻ thẳng thắn với bố hoặc người lớn tin cậy.", "nextNode": "step2"}]}, "step2": {"text": "Cơn đau tức tinh hoàn không giảm sau 2 tiếng, bạn cùng lớp khuyên Nam cứ nằm nghỉ chịu đau qua đêm là tự khỏi, không cần đi bệnh viện.", "choices": [{"text": "Nghe bạn nằm chịu đau ở nhà để tránh việc phải cởi đồ cho bác sĩ kiểm tra vùng nhạy cảm.", "nextNode": "fail_wait"}, {"text": "Cương quyết nhờ bố đưa đi bệnh viện khám nam khoa/ngoại khoa ngay vì nghi ngờ nguy cơ xoắn tinh hoàn.", "nextNode": "step3"}]}, "step3": {"text": "Khi đang đứng phát biểu bài trước lớp học, dương vật của Nam bỗng nhiên cương cứng bất ngờ (hiện tượng sinh lý bình thường) làm Nam đỏ bừng mặt.", "choices": [{"text": "Hoảng loạn khóc lóc và chạy ngay ra khỏi lớp học để trốn tránh các bạn.", "nextNode": "fail_panic"}, {"text": "Bình tĩnh đặt cuốn sách hoặc hộp bút che phía trước quần, hít thở sâu để phân tán suy nghĩ và đợi dương vật tự xẹp xuống.", "nextNode": "step4"}]}, "step4": {"text": "Sau giờ học, một bạn học đùa dai chạy đến túm quần cố tình kéo tụt quần Nam xuống trước mặt các bạn khác để trêu đùa.", "choices": [{"text": "Không làm gì cả, cố cười trừ xem như trò đùa vô hại để giữ hòa khí.", "nextNode": "fail_laugh"}, {"text": "Kéo quần lên ngay lập tức, nhìn thẳng bạn đó và nói rõ: \"Đây là đùa cợt thô lỗ xâm phạm cơ thể tớ, tớ yêu cầu cậu không được lặp lại.\"", "nextNode": "step5"}]}, "step5": {"text": "Bạn đó vẫn tiếp tục cười cợt và rủ các bạn khác tham gia đùa giỡn, đe dọa sẽ tụt quần Nam lần nữa vào ngày mai.", "choices": [{"text": "Báo cáo ngay sự việc với giáo viên chủ nhiệm hoặc ban giám hiệu nhà trường để được can thiệp bảo vệ.", "nextNode": "success_end"}, {"text": "Âm thầm chịu đựng và quyết định trốn học ngày mai để tránh bị quấy rối.", "nextNode": "fail_run"}]}, "success_end": {"text": "🎉 Xuất sắc! Bạn đã bảo vệ bản thân thông thái trước các nguy cơ nam khoa nguy hiểm, xử lý cương cứng bất ngờ và thiết lập ranh giới cơ thể vững chắc.", "isEnd": true, "isSuccess": true}, "fail_silent": {"text": "❌ Chưa đúng! Giấu đau tinh hoàn và tự uống thuốc giảm đau có thể che lấp triệu chứng nguy cấp của bệnh xoắn tinh hoàn gây hoại tử.", "isEnd": true, "isSuccess": false}, "fail_wait": {"text": "❌ Chưa đúng! Xoắn tinh hoàn là ca cấp cứu y khoa khẩn cấp, nếu chậm trễ quá 6 tiếng có thể phải cắt bỏ tinh hoàn dẫn đến vô sinh nam.", "isEnd": true, "isSuccess": false}, "fail_panic": {"text": "❌ Sai rồi! Cương cứng bất ngờ là phản xạ sinh học hoàn toàn tự nhiên của bạn trai dậy thì, hoảng loạn bỏ chạy chỉ khiến mọi người chú ý hơn.", "isEnd": true, "isSuccess": false}, "fail_laugh": {"text": "❌ Sai rồi! Chấp nhận trò đùa thô bạo sẽ khiến đối phương nghĩ bạn đồng thuận, làm lu mờ ranh giới cá nhân của bạn.", "isEnd": true, "isSuccess": false}, "fail_run": {"text": "❌ Sai rồi! Trốn học không giải quyết được vấn đề mà làm bạn bị gián đoạn học tập, hãy tìm kiếm sự bảo vệ từ nhà trường và bố mẹ.", "isEnd": true, "isSuccess": false}}}', 2),
(@ml_id, 'sorting', '{"instruction": "Hãy phân loại các hành vi ứng xử với cơ thể dưới đây:", "leftBox": {"title": "Tự chăm sóc đúng"}, "rightBox": {"title": "Nguy hiểm / Sai lệch"}, "items": [{"text": "Khám nam khoa ngay khi bị đau tức tinh hoàn", "correctBox": "left"}, {"text": "Tự ý mua thuốc giảm đau khi đau tinh hoàn", "correctBox": "right"}, {"text": "Thực hiện tự khám tinh hoàn hàng tháng", "correctBox": "left"}, {"text": "Đùa cợt khiếm nhã kéo quần bạn cùng lớp", "correctBox": "right"}, {"text": "Giữ bình tĩnh khi cương cứng bất ngờ", "correctBox": "left"}, {"text": "Thụt rửa sâu vào trong âm đạo bạn gái", "correctBox": "right"}, {"text": "Lau rửa bộ phận sinh dục ngoài bằng nước ấm", "correctBox": "left"}, {"text": "Chọc ghẹo bình phẩm khiếm nhã về ngực bạn gái", "correctBox": "right"}, {"text": "Từ chối thẳng thắn đụng chạm không mong muốn", "correctBox": "left"}, {"text": "Cố nằm im chịu đựng đau bìu dữ dội qua đêm", "correctBox": "right"}]}', 3),
(@ml_id, 'matching', '{"instruction": "Ghép cặp các bộ phận giải phẫu với định nghĩa y khoa tương ứng:", "pairs": [{"left": "Tinh hoàn", "right": "Cơ quan sản xuất tinh trùng và hormone nam"}, {"left": "Bao quy đầu", "right": "Lớp da bao bọc bảo vệ đầu dương vật"}, {"left": "Xoắn tinh hoàn", "right": "Cấp cứu y khoa khẩn cấp cần phẫu thuật tháo xoắn sớm"}, {"left": "Cương cứng bất ngờ", "right": "Phản xạ sinh học tự nhiên khi máu dồn về dương vật"}, {"left": "Tự khám tinh hoàn", "right": "Hành động sờ nắn tìm cục u lạ hàng tháng tại nhà"}, {"left": "Quy tắc đồ bơi", "right": "Quy ước bảo vệ tuyệt đối không ai được chạm vào vùng nhạy cảm"}, {"left": "Âm đạo", "right": "Kênh cơ nối cổ tử cung ra phía ngoài cơ thể nữ"}, {"left": "Ranh giới cá nhân", "right": "Khoảng cách an toàn về thể chất và cảm xúc do bạn quyết định"}]}', 4),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 1: Điền từ thích hợp về bảo vệ sức khỏe hệ sinh dục nam:", "sentence": "Tinh hoàn của bạn trai nằm trong bìu, có nhiệm vụ sản xuất tinh trùng và [blank1]. Nếu gặp chấn thương khi chơi thể thao dẫn đến đau tức bìu dữ dội kèm [blank2], bạn cần được đưa đi [blank3] ngay lập tức để loại trừ xoắn tinh hoàn. Việc tự ý uống thuốc [blank4] hoặc chịu đựng đau quá 6 tiếng có thể dẫn đến hoại tử tinh hoàn. Hãy dũng cảm [blank5] với bố mẹ hoặc người lớn tin cậy để cấp cứu kịp thời.", "blanks": {"blank1": {"correct": "testosterone", "placeholder": "..."}, "blank2": {"correct": "buồn nôn", "placeholder": "..."}, "blank3": {"correct": "cấp cứu", "placeholder": "..."}, "blank4": {"correct": "giảm đau", "placeholder": "..."}, "blank5": {"correct": "chia sẻ", "placeholder": "..."}}, "words": ["testosterone", "buồn nôn", "cấp cứu", "giảm đau", "chia sẻ", "estrogen", "sốt nhẹ", "khám da", "bổ thận", "giấu kín"]}', 5),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 2: Điền từ thích hợp về quy tắc bảo vệ ranh giới cơ thể:", "sentence": "Quy tắc đồ bơi quy định rằng bất kỳ ai cũng không được [blank1] vào vùng cơ thể nhạy cảm của bạn. Bạn có quyền từ chối [blank2] mọi đụng chạm khiến bản thân thấy khó chịu hoặc sợ hãi. Nếu có người cố tình vi phạm ranh giới đó, hãy hét lớn, [blank3] khỏi nơi đó và báo ngay cho người lớn. Đừng giữ bí mật vì cảm thấy [blank4] hay tội lỗi. Sự an toàn và [blank5] cơ thể của bạn là trên hết.", "blanks": {"blank1": {"correct": "chạm", "placeholder": "..."}, "blank2": {"correct": "dứt khoát", "placeholder": "..."}, "blank3": {"correct": "chạy thoát", "placeholder": "..."}, "blank4": {"correct": "xấu hổ", "placeholder": "..."}, "blank5": {"correct": "quyền tự chủ", "placeholder": "..."}}, "words": ["chạm", "dứt khoát", "chạy thoát", "xấu hổ", "quyền tự chủ", "nhìn", "ngập ngừng", "nằm im", "tự hào", "sở thích"]}', 6),
(@ml_id, 'interaction', '{"question": "Khi bị đau tức tinh hoàn cấp tính kèm buồn nôn sau khi va chạm thể thao, hành động nào là đúng?", "choices": [{"text": "Đến ngay cơ sở y tế gần nhất trong vòng 6 giờ đầu để kiểm tra loại trừ xoắn tinh hoàn.", "correct": true, "emoji": "💚"}, {"text": "Chườm đá lạnh và nằm im một chỗ chờ 2-3 ngày xem cơn đau có tự biến mất không.", "correct": false, "emoji": "🛑"}]}', 7),
(@ml_id, 'interaction', '{"question": "Thao tác tự kiểm tra tinh hoàn hàng tháng tại nhà giúp bạn trai phát hiện sớm điều gì?", "choices": [{"text": "Các cục u nhỏ, sưng tấy hoặc thay đổi kích thước bất thường nghi ngờ ung thư tinh hoàn.", "correct": true, "emoji": "💚"}, {"text": "Số lượng tinh trùng nhiều hay ít để đánh giá khả năng sinh sản trực quan của bản thân.", "correct": false, "emoji": "🛑"}]}', 8),
(@ml_id, 'interaction', '{"question": "Tại sao việc đùa cợt tụt quần bạn khác trong trường lại bị coi là hành vi xâm hại ranh giới nghiêm trọng?", "choices": [{"text": "Vì nó vi phạm quy tắc đồ bơi, quấy rối tình dục và gây tổn thương lòng tự trọng của bạn.", "correct": true, "emoji": "💚"}, {"text": "Vì hành động này làm bạn bị nhiễm lạnh đột ngột ảnh hưởng đến sức khỏe thể chất.", "correct": false, "emoji": "🛑"}]}', 9),
(@ml_id, 'interaction', '{"question": "Khi một người cố gắng đụng chạm vùng kín của bạn và hăm dọa không được nói với ai, bạn nên làm gì?", "choices": [{"text": "Từ chối quyết liệt, chạy thoát và báo ngay với bố mẹ hoặc thầy cô giáo tin cậy.", "correct": true, "emoji": "💚"}, {"text": "Âm thầm chịu đựng và giấu kín chuyện này vì nghĩ mình có lỗi.", "correct": false, "emoji": "🛑"}]}', 10),
(@ml_id, 'interaction', '{"question": "Hiện tượng dương vật cương cứng bất ngờ vào ban ngày không đi kèm suy nghĩ kích thích ở tuổi dậy thì là do đâu?", "choices": [{"text": "Phản xạ sinh lý tự nhiên khi hormone sinh dục tăng cao và điều hòa mạch máu.", "correct": true, "emoji": "💚"}, {"text": "Dấu hiệu cảnh báo bệnh rối loạn chức năng sinh lý cần phẫu thuật gấp.", "correct": false, "emoji": "🛑"}]}', 11);
INSERT INTO lessons (course_id, slug, title, summary, content, lesson_order, is_free, xp_reward, estimated_minutes)
INSERT INTO lesson_sources (lesson_id, source_name, source_url, source_type) VALUES
(@lesson4_id, 'Scarleteen - Periods and the Menstrual Cycle', 'https://www.scarleteen.com/read/bodies/quickies-periods-menstrual-cycle', 'website');
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson4_id, 'Kinh nguyệt đầu tiên là gì?', 1);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có hoang mang nếu một ngày phát hiện một vệt máu đỏ tươi xuất hiện trên chiếc quần lót của mình?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Kinh nguyệt đầu tiên (menarche) là dấu hiệu sinh lý tự nhiên khẳng định buồng trứng của bạn gái đã bắt đầu hoạt động.", "Mỗi tháng, tử cung chuẩn bị một lớp niêm mạc êm ái để đón trứng thụ tinh. Nếu trứng không được thụ tinh, lớp niêm mạc này sẽ bong ra và thoát ra ngoài qua âm đạo dưới dạng máu kinh.", "Đây hoàn toàn là máu sạch của cơ thể, không phải là chất bẩn dơ độc như các quan niệm cổ hủ."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống hoảng loạn", "body": "Trong giờ học thể dục, Lan bỗng thấy vùng kín ẩm ướt. Khi vào nhà vệ sinh, Lan phát hiện quần mình dính đầy máu. Lan khóc nức nở vì nghĩ mình bị chấn thương chảy máu bên trong sắp chết."}', 3),
(@ml_id, 'interaction', '{"question": "Nếu là bạn học đi cùng Lan vào nhà vệ sinh lúc đó, bạn nên hỗ trợ Lan như thế nào?", "choices": [{"text": "Ôm trấn an bạn: ''Cậu không sao đâu, đây là kinh nguyệt đầu tiên thôi!'', hướng dẫn bạn dùng băng vệ sinh và xin cô giáo cho nghỉ.", "correct": true, "emoji": "💚"}, {"text": "Hoảng sợ chạy đi gọi xe cấp cứu y tế hoặc đứng cười trêu chọc bạn làm bạn thêm hoảng loạn.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã chuẩn bị những kiến thức và sản phẩm vệ sinh cần thiết cho kỳ kinh nguyệt đầu tiên của mình chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Kinh nguyệt là tín hiệu cơ thể bạn đang bước vào hành trình làm mẹ kỳ diệu trong tương lai."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson4_id, 'Các giai đoạn của chu kỳ kinh nguyệt', 2);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có biết chu kỳ kinh nguyệt thực ra hoạt động như một vòng tuần hoàn của bốn mùa trong tháng?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Một chu kỳ kinh nguyệt chuẩn tính từ ngày đầu tiên ra máu của kỳ này đến ngày đầu tiên ra máu của kỳ tiếp theo, thường kéo dài từ 21 đến 35 ngày.", "Chu kỳ gồm 4 giai đoạn: Giai đoạn hành kinh (mùa đông), Giai đoạn trước rụng trứng (mùa xuân), Giai đoạn rụng trứng (mùa hè) và Giai đoạn sau rụng trứng (mùa thu).", "Hormone estrogen và progesterone biến động liên tục trong các giai đoạn này tạo nên sự thay đổi về năng lượng và tâm trạng."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống ẩm ương", "body": "Vy thấy tuần trước mình tràn đầy năng lượng, vui vẻ chơi đùa, nhưng tuần này bỗng thấy sụt giảm năng lượng, dễ buồn khóc vô cớ và thèm ăn đồ ngọt liên tục dù chưa đến ngày hành kinh."}', 3),
(@ml_id, 'interaction', '{"question": "Sự biến đổi tâm trạng và năng lượng đột ngột của Vy do đâu?", "choices": [{"text": "Do hội chứng tiền kinh nguyệt", "correct": true, "emoji": "💚"}, {"text": "Do Vy lười biếng và thiếu kỷ luật bản thân nên mới để cảm xúc chi phối cuộc sống.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có thói quen theo dõi ngày hành kinh của mình để nhận diện các giai đoạn thay đổi năng lượng không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Lắng nghe chu kỳ giúp bạn làm chủ nhịp điệu sinh học của chính mình."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson4_id, 'Quản lý đau bụng kinh và khó chịu', 3);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để dập tắt cơn đau bụng âm ỉ như bị bóp nghẹt mỗi khi kỳ kinh nguyệt ghé thăm?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Cơn đau bụng kinh (cramps) xảy ra do tử cung co thắt để đẩy lớp niêm mạc ra ngoài dưới tác động của chất prostaglandins.", "Đau bụng âm ỉ, đau lưng nhẹ hay mỏi đùi là những hiện tượng phổ biến và có thể thuyên giảm bằng các biện pháp tự chăm sóc ấm áp.", "Tuy nhiên, nếu cơn đau dữ dội làm bạn ngất xỉu, nôn mửa hoặc không thể đi học, đó có thể là cờ đỏ y khoa cần đi khám chuyên khoa."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống đau đớn", "body": "Linh bị đau quặn bụng dưới trong ngày đầu tiên của kỳ kinh. Cơn đau khiến Linh toát mồ hôi hột, chỉ muốn nằm co quắp trên giường và không thể tập trung học bài."}', 3),
(@ml_id, 'interaction', '{"question": "Linh nên dùng phương pháp tự nhiên nào để làm dịu cơn co thắt bụng kinh hiệu quả?", "choices": [{"text": "Uống nước ấm, chườm ấm vùng bụng dưới và thực hiện các động tác yoga nhẹ nhàng thư giãn cơ.", "correct": true, "emoji": "💚"}, {"text": "Cố gồng mình chịu đựng, nhịn uống nước và uống ngay 3 viên thuốc giảm đau liều mạnh khi chưa ăn gì.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn thường áp dụng phương pháp nào để chăm sóc cơ thể và giảm bớt khó chịu trong những ngày đèn đỏ?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Chườm ấm và nghỉ ngơi là liều thuốc dịu dàng nhất cho tử cung của bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson4_id, 'Lựa chọn sản phẩm vệ sinh phù hợp', 4);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có hoa mắt trước hàng tá loại sản phẩm nguyệt san từ băng vệ sinh, tampon cho đến cốc nguyệt san?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Mỗi sản phẩm vệ sinh đều có ưu, nhược điểm riêng phù hợp với từng nhu cầu vận động và cơ địa.", "**Băng vệ sinh (pads)**: Dễ dùng, an toàn bên ngoài, cần thay sau mỗi 3-4 tiếng để tránh vi khuẩn sinh sôi.", "**Tampon** và **Cốc nguyệt san (menstrual cup)**: Dùng đặt trong âm đạo, giúp thoải mái vận động dưới nước, đòi hỏi kỹ năng vệ sinh tay và cách đặt chuẩn xác."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống đi bơi", "body": "Mai chuẩn bị tham gia hội thao bơi lội của trường thì kỳ kinh nguyệt đột ngột ghé thăm. Mai vô cùng thất vọng và định xin rút lui khỏi giải bơi yêu thích."}', 3),
(@ml_id, 'interaction', '{"question": "Giải pháp nào giúp Mai vẫn có thể tham gia thi bơi lội an toàn và thoải mái?", "choices": [{"text": "Tìm hiểu cách sử dụng tampon hoặc cốc nguyệt san phù hợp dưới sự hướng dẫn y khoa hoặc người lớn đáng tin.", "correct": true, "emoji": "💚"}, {"text": "Dán băng vệ sinh thông thường loại dày nhất và mặc quần bơi thật chặt để đi bơi tiếp.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã tự tin biết cách thay và xử lý băng vệ sinh đã qua sử dụng một cách văn minh và sạch sẽ chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Sản phẩm tốt nhất là sản phẩm khiến bạn cảm thấy thoải mái và an toàn nhất."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson4_id, 'Theo dõi chu kỳ bằng công nghệ', 5);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để không bao giờ bị rơi vào tình thế dở khóc dở cười khi kỳ kinh nguyệt đột ngột xuất hiện không báo trước?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Kinh nguyệt tuổi dậy thì thường không đều trong 1-2 năm đầu do hệ hormone chưa ổn định.", "Việc ghi chép và theo dõi chu kỳ giúp bạn dự đoán tương đối ngày đèn đỏ tiếp theo để chủ động chuẩn bị đồ dùng vệ sinh.", "Các ứng dụng công nghệ (Period tracker apps) hoặc lịch giấy nhỏ là công cụ đắc lực hỗ trợ bạn ghi chép dễ dàng."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống bất ngờ", "body": "Vy đang đi cắm trại cùng lớp thì kỳ kinh nguyệt đột ngột ghé thăm làm bẩn quần jean trắng của Vy. Vy không mang theo băng vệ sinh dự phòng và thấy vô cùng bối rối, khóc lóc muốn đi về."}', 3),
(@ml_id, 'interaction', '{"question": "Thói quen chủ động nào dưới đây giúp Vy tránh được sự cố dở khóc dở cười này trong các chuyến đi sau?", "choices": [{"text": "Sử dụng app theo dõi chu kỳ, luôn mang theo một túi nguyệt san nhỏ dự phòng trong ba lô bất kể ngày nào.", "correct": true, "emoji": "💚"}, {"text": "Không đi cắm trại hay tham gia các hoạt động dã ngoại ngoài trời nữa để đảm bảo an toàn tuyệt đối.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có đang sử dụng ứng dụng hoặc cuốn sổ nào để theo dõi chu kỳ nguyệt san của mình không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Ghi chép chu kỳ là cách bạn trò chuyện và thấu hiểu lịch trình sinh học của cơ thể."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson4_id, 'Gạt bỏ những lầm tưởng về nguyệt san', 6);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có từng nghe ai đó bảo con gái đến ngày đèn đỏ thì không được tắm gội hay chạm vào cây cối vì sẽ làm cây chết héo?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Có rất nhiều quan niệm sai lầm, cổ hủ xung quanh kỳ kinh nguyệt do thiếu kiến thức khoa học.", "Thực tế: Bạn hoàn toàn có thể tắm rửa, gội đầu sạch sẽ bằng nước ấm (giúp giảm đau), vận động thể thao nhẹ nhàng và sinh hoạt hoàn toàn bình thường.", "Kinh nguyệt là hiện tượng sinh lý sạch sẽ, lành mạnh, không có gì là dơ bẩn, xui xẻo hay phải giấu giếm như một tội lỗi."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống kiêng cữ", "body": "Bà nội bảo Lan đến ngày kinh nguyệt thì tuyệt đối không được gội đầu hay tắm rửa trong suốt 5 ngày vì sẽ bị nhiễm lạnh vào tận xương tủy sau này. Lan thấy cơ thể ngứa ngáy, bẩn thỉu và rất khó chịu."}', 3),
(@ml_id, 'interaction', '{"question": "Lan nên cư xử thế nào trước lời khuyên kiêng cữ của bà nội?", "choices": [{"text": "Giải thích nhẹ nhàng với bà dựa trên kiến thức khoa học mới, vẫn giữ vệ sinh tắm gội bằng nước ấm sạch sẽ để cơ thể thoải mái.", "correct": true, "emoji": "💚"}, {"text": "Ngoan ngoãn nghe lời bà nhịn tắm gội hoàn toàn trong 5 ngày dù ngứa ngáy và bốc mùi khó chịu.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Gia đình hoặc nơi bạn sống có những quan niệm kiêng cữ nào về ngày đèn đỏ mà bạn thấy vô lý không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Kinh nguyệt là tự nhiên và khoa học, hãy tắm gội sạch sẽ để cơ thể được yêu thương."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson4_id, 'Bài kiểm tra: Thử thách tổng kết', 99);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Chào mừng bạn đến với Thử thách Tổng kết bài học ''Chu kỳ kinh nguyệt & Phát triển sinh sản''! Cùng nâng cao kỹ năng xử lý nguyệt san và bảo vệ sức khỏe phụ khoa."}', 1),
(@ml_id, 'scenario-choice', '{"title": "Ứng phó trễ kinh và đau bụng kinh nguy cấp", "startNode": "step1", "nodes": {"step1": {"text": "Vy bị trễ kinh 2 tháng nay dù trước đó chu kỳ khá đều. Vy rất lo sợ và chia sẻ với bạn cùng nhóm chat.", "choices": [{"text": "Tự ý mua các loại thuốc nội tiết tố trên mạng về uống để kích thích ra kinh.", "nextNode": "fail_meds"}, {"text": "Tìm hiểu thông tin khoa học, nhận thấy chu kỳ kinh nguyệt những năm đầu dậy thì chưa ổn định và theo dõi tiếp.", "nextNode": "step2"}]}, "step2": {"text": "Bạn cùng nhóm mách Vy nên ăn thật nhiều dứa và uống nước dừa liên tục cả ngày để kinh nguyệt lập tức xuất hiện.", "choices": [{"text": "Ăn dứa thay cơm và uống nước dừa dồn dập suốt cả ngày.", "nextNode": "fail_pineapple"}, {"text": "Duy trì ăn uống đủ chất, ghi chép chu kỳ bằng ứng dụng và tiếp tục theo dõi.", "nextNode": "step3"}]}, "step3": {"text": "Kỳ kinh nguyệt đến, lần này Vy bị đau bụng kinh dữ dội kèm theo sốt cao 38.5 độ và chóng mặt.", "choices": [{"text": "Nghĩ là đau bụng kinh thông thường, tự ý uống 3 viên thuốc giảm đau liều mạnh rồi nằm ngủ.", "nextNode": "fail_fever"}, {"text": "Báo ngay cho mẹ để được đưa đi khám bác sĩ chuyên khoa phụ sản vì đau bụng kinh không đi kèm sốt cao.", "nextNode": "step4"}]}, "step4": {"text": "Tại bệnh viện, Vy được kê đơn kháng sinh điều trị viêm nhiễm và hướng dẫn tần suất thay băng vệ sinh.", "choices": [{"text": "Chỉ thay băng vệ sinh 1 lần mỗi ngày khi thấy lượng máu kinh ra ít để tiết kiệm băng.", "nextNode": "fail_hygiene"}, {"text": "Tuân thủ thay băng vệ sinh sau mỗi 3-4 tiếng kể cả khi máu kinh ra ít để ngăn vi khuẩn tích tụ.", "nextNode": "step5"}]}, "step5": {"text": "Khi tắm rửa trong những ngày hành kinh, Vy thấy trên mạng khuyên nên dùng vòi xịt nước áp lực mạnh để thụt rửa sâu bên trong cho hết máu bẩn.", "choices": [{"text": "Thụt rửa sâu âm đạo bằng vòi nước mạnh để làm sạch sâu.", "nextNode": "fail_douching"}, {"text": "Chỉ rửa nhẹ nhàng vùng âm hộ bên ngoài bằng nước sạch hoặc dung dịch vệ sinh phù hợp.", "nextNode": "success_end"}]}, "success_end": {"text": "🎉 Hoàn thành xuất sắc! Bạn đã biết cách quản lý chu kỳ nguyệt san khoa học, nhận biết triệu chứng nguy hiểm, vệ sinh vùng kín an toàn.", "isEnd": true, "isSuccess": true}, "fail_meds": {"text": "❌ Chưa đúng! Tự ý uống thuốc nội tiết tố rất nguy hiểm, có thể gây rối loạn chu kỳ nặng hơn và hại buồng trứng.", "isEnd": true, "isSuccess": false}, "fail_pineapple": {"text": "❌ Chưa đúng! Ăn quá nhiều dứa khi đói làm dạ dày bị cồn cào, loét niêm mạc do axit cao mà không giúp kích thích ra kinh.", "isEnd": true, "isSuccess": false}, "fail_fever": {"text": "❌ Sai rồi! Đau bụng kinh thông thường không bao giờ kèm sốt cao. Đây là tín hiệu cấp cứu y tế, tự uống thuốc giảm đau liều mạnh sẽ che giấu bệnh nguy hiểm.", "isEnd": true, "isSuccess": false}, "fail_hygiene": {"text": "❌ Sai rồi! Để băng vệ sinh quá lâu làm tích tụ vi khuẩn gây mùi và dẫn đến nhiễm trùng ngược dòng nguy hiểm.", "isEnd": true, "isSuccess": false}, "fail_douching": {"text": "❌ Sai rồi! Thụt rửa sâu âm đạo phá hủy hệ lợi khuẩn âm đạo, tạo điều kiện cho vi sinh vật có hại phát triển gây viêm nhiễm nặng nề.", "isEnd": true, "isSuccess": false}}}', 2),
(@ml_id, 'sorting', '{"instruction": "Hãy phân loại các thói quen chăm sóc nguyệt san dưới đây:", "leftBox": {"title": "Nên làm (Lành mạnh)"}, "rightBox": {"title": "Tránh làm (Có hại)"}, "items": [{"text": "Thay băng vệ sinh sau mỗi 3-4 tiếng", "correctBox": "left"}, {"text": "Nhịn gội đầu tắm rửa suốt cả kỳ kinh", "correctBox": "right"}, {"text": "Ghi chép lịch kinh nguyệt bằng ứng dụng di động", "correctBox": "left"}, {"text": "Ăn dứa thay cơm để kích thích kinh ra nhanh", "correctBox": "right"}, {"text": "Chườm ấm bụng dưới khi bị đau bụng kinh nhẹ", "correctBox": "left"}, {"text": "Tự ý uống thuốc nội tiết tố khi bị trễ kinh", "correctBox": "right"}, {"text": "Rửa tay sạch trước và sau khi thay băng vệ sinh", "correctBox": "left"}, {"text": "Thụt rửa sâu âm đạo bằng vòi nước áp lực mạnh", "correctBox": "right"}, {"text": "Mặc quần lót sạch làm bằng chất liệu cotton", "correctBox": "left"}, {"text": "Dùng sữa tắm chà xát thật sâu vào âm hộ", "correctBox": "right"}]}', 3),
(@ml_id, 'matching', '{"instruction": "Ghép cặp các khái niệm y khoa với đặc điểm tương ứng:", "pairs": [{"left": "Băng vệ sinh", "right": "Sản phẩm dùng bên ngoài âm hộ, dễ thay nhất"}, {"left": "Tampon", "right": "Băng vệ sinh dạng que nén đặt trong âm đạo"}, {"left": "Cốc nguyệt san", "right": "Cốc silicon thu thập dịch kinh thân thiện môi trường"}, {"left": "Đau bụng kinh kèm sốt", "right": "Triệu chứng nguy cấp cần đi bệnh viện khám ngay"}, {"left": "Hội chứng tiền kinh nguyệt", "right": "Các triệu chứng mệt mỏi, nhạy cảm trước kỳ kinh"}, {"left": "Chườm ấm bụng", "right": "Biện pháp nhiệt vật lý giúp giãn cơ tử cung"}, {"left": "Thụt rửa âm đạo", "right": "Hành vi có hại làm mất cân bằng độ pH vùng kín"}, {"left": "Niêm mạc tử cung", "right": "Lớp màng bong ra tạo thành dịch kinh nguyệt"}]}', 4),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 1: Điền từ thích hợp về chu kỳ kinh nguyệt và theo dõi sức khỏe:", "sentence": "Kinh nguyệt là sự bong tróc lớp niêm mạc tử cung khi không có sự [blank1]. Những năm đầu dậy thì, chu kỳ kinh nguyệt thường [blank2] do hoạt động hormone chưa ổn định. Bạn gái nên sử dụng ứng dụng để [blank3] ngày bắt đầu và kết thúc kỳ kinh. Nếu gặp tình trạng đau bụng kinh dữ dội kèm [blank4] cao hoặc khí hư có mùi tanh, bạn cần đi khám [blank5] ngay.", "blanks": {"blank1": {"correct": "thụ tinh", "placeholder": "..."}, "blank2": {"correct": "thất thường", "placeholder": "..."}, "blank3": {"correct": "theo dõi", "placeholder": "..."}, "blank4": {"correct": "sốt", "placeholder": "..."}, "blank5": {"correct": "phụ khoa", "placeholder": "..."}}, "words": ["thụ tinh", "thất thường", "theo dõi", "sốt", "phụ khoa", "rụng trứng", "đều đặn", "bỏ qua", "lạnh bụng", "da liễu"]}', 5),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 2: Điền từ thích hợp về cách vệ sinh vùng kín ngày đèn đỏ:", "sentence": "Trong những ngày hành kinh, việc thay băng vệ sinh sau mỗi [blank1] tiếng là cực kỳ cần thiết để ngăn ngừa vi khuẩn sinh sôi. Kể cả khi lượng máu kinh ra [blank2], bạn vẫn không nên để băng quá lâu. Khi sử dụng các sản phẩm đặt trong như tampon hay cốc nguyệt san, hãy nhớ vệ sinh [blank3] thật sạch trước khi thao tác. Tránh thụt rửa sâu vào trong [blank4] vì việc này làm xáo trộn độ pH tự nhiên, tăng nguy cơ [blank5] phụ khoa.", "blanks": {"blank1": {"correct": "3 đến 4", "placeholder": "..."}, "blank2": {"correct": "rất ít", "placeholder": "..."}, "blank3": {"correct": "bàn tay", "placeholder": "..."}, "blank4": {"correct": "âm đạo", "placeholder": "..."}, "blank5": {"correct": "nhiễm trùng", "placeholder": "..."}}, "words": ["3 đến 4", "rất ít", "bàn tay", "âm đạo", "nhiễm trùng", "8 đến 10", "nhiều", "dụng cụ", "tử cung", "vô sinh"]}', 6),
(@ml_id, 'interaction', '{"question": "Khi bị đau bụng kinh kèm sốt cao trên 38.5 độ và khí hư có mùi hôi tanh nồng nặc, bạn nên làm gì?", "choices": [{"text": "Báo ngay cho bố mẹ để đi khám bác sĩ chuyên khoa phụ sản vì có nguy cơ nhiễm trùng phụ khoa.", "correct": true, "emoji": "💚"}, {"text": "Tự mua thuốc giảm đau uống và xông hơi vùng kín bằng nước lá trầu không tại nhà.", "correct": false, "emoji": "🛑"}]}', 7),
(@ml_id, 'interaction', '{"question": "Tại sao việc thay băng vệ sinh sau mỗi 3-4 tiếng lại bắt buộc ngay cả khi lượng máu kinh ra rất ít?", "choices": [{"text": "Vì máu kinh ẩm ướt kết hợp nhiệt độ cơ thể tạo môi trường lý tưởng cho vi khuẩn sinh sôi cực nhanh sau 4 tiếng.", "correct": true, "emoji": "💚"}, {"text": "Vì băng vệ sinh sẽ tự động phân hủy sau 4 tiếng gây hại cho làn da nhạy cảm.", "correct": false, "emoji": "🛑"}]}', 8),
(@ml_id, 'interaction', '{"question": "Hiện tượng trễ kinh hoặc chu kỳ kinh không đều ở các bạn gái trong 1-2 năm đầu dậy thì thường do nguyên nhân gì?", "choices": [{"text": "Do hệ trục não bộ - tuyến yên - buồng trứng chưa phát triển hoàn thiện, hoạt động hormone chưa ổn định.", "correct": true, "emoji": "💚"}, {"text": "Do bạn đã bị vô sinh hoặc mắc các bệnh phụ khoa mãn tính nguy hiểm.", "correct": false, "emoji": "🛑"}]}', 9),
(@ml_id, 'interaction', '{"question": "Dùng xà phòng tắm thông thường có tính kiềm cao chà rửa sâu bên trong âm hộ bạn gái có thể gây hại như thế nào?", "choices": [{"text": "Tiêu diệt hệ lợi khuẩn âm đạo Lactobacilli và gây kích ứng khô rát niêm mạc vùng kín.", "correct": true, "emoji": "💚"}, {"text": "Khiến nước xà phòng ngấm vào mạch máu tử cung gây ngộ độc hệ sinh sản.", "correct": false, "emoji": "🛑"}]}', 10),
(@ml_id, 'interaction', '{"question": "Cách sử dụng băng vệ sinh hàng ngày (loại nhỏ) an toàn cho sức khỏe bạn gái là gì?", "choices": [{"text": "Chỉ dùng khi ra khí hư nhiều hoặc cuối chu kỳ và phải thay sau mỗi 3-4 tiếng để tránh nhiễm khuẩn ngược dòng.", "correct": true, "emoji": "💚"}, {"text": "Dán liên tục từ sáng đến tối mà không cần thay vì lượng dịch ra rất ít.", "correct": false, "emoji": "🛑"}]}', 11);
INSERT INTO lessons (course_id, slug, title, summary, content, lesson_order, is_free, xp_reward, estimated_minutes)
INSERT INTO lesson_sources (lesson_id, source_name, source_url, source_type) VALUES
(@lesson5_id, 'Scarleteen - The Scarleteen Do-It', 'https://www.scarleteen.com/read/bodies/do-it', 'website');
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson5_id, 'Tầm quan trọng của vệ sinh tuổi dậy thì', 1);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Tại sao thói quen vệ sinh trước đây của bạn bỗng trở nên không đủ sạch khi bước vào tuổi dậy thì?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Tuyến mồ hôi và tuyến bã nhờn hoạt động với công suất gấp đôi ở tuổi dậy thì, tạo môi trường thuận lợi cho vi khuẩn phát sinh.", "Vệ sinh cá nhân không chỉ giúp cơ thể thơm tho, phòng ngừa các bệnh ngoài da mà còn mang lại sự tự tin giao tiếp xã hội.", "Xây dựng thói quen tắm rửa, giặt giũ quần áo hàng ngày là bước đệm cơ bản của lối sống tự lập."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống lười biếng", "body": "Nam đi học về mệt mỏi, nằm ườn ra giường chơi game và đi ngủ luôn mà không tắm rửa hay thay quần áo vì nghĩ: \"Trời mát mẻ có ra mồ hôi đâu mà bẩn\". Sáng hôm sau, Nam thấy cơ thể ngứa ngáy khó chịu."}', 3),
(@ml_id, 'interaction', '{"question": "Hành vi lười tắm rửa của Nam kéo dài sẽ dẫn tới hậu quả gì?", "choices": [{"text": "Mồ hôi và tế bào chết tích tụ gây mùi hôi nách, ngứa ngáy và viêm da dị ứng.", "correct": true, "emoji": "💚"}, {"text": "Không sao cả, chỉ cần xịt thêm nước hoa vào buổi sáng là cơ thể lại thơm tho đi học tiếp.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có đang duy trì thói quen tắm rửa và thay quần lót sạch sẽ đều đặn mỗi ngày không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Sạch sẽ là tấm áo giáp đầu tiên bảo vệ sức khỏe và sự tự tin của bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson5_id, 'Chăm sóc làn da ẩm ương', 2);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để đối phó với làn da bỗng dưng nổi loạn đầy dầu nhờn và mụn bọc?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Làn da tuổi dậy thì cực kỳ nhạy cảm do sự xáo trộn hormone kích thích dầu thừa.", "Quy trình chăm sóc da cơ bản gồm 3 bước đơn giản: Làm sạch nhẹ nhàng (Cleansing), Dưỡng ẩm dịu nhẹ (Moisturizing) và Bảo vệ chống nắng (Sunscreen).", "Tránh tự ý nặn mụn bằng tay bẩn hoặc dùng các sản phẩm kem trộn tàn phá hàng rào bảo vệ da."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống nặn mụn", "body": "Linh thấy xuất hiện vài nốt mụn trứng cá trên má. Linh thấy ngứa ngáy khó chịu, liên tục dùng tay cậy, nặn mụn trước gương. Kết quả là các nốt mụn bị sưng tấy đỏ lòm và loét rộng ra."}', 3),
(@ml_id, 'interaction', '{"question": "Linh nên thay đổi thói quen chăm sóc mụn này như thế nào để da nhanh lành?", "choices": [{"text": "Rửa mặt bằng sữa rửa mặt dịu nhẹ, giữ tay sạch không chạm lên mặt và chấm thuốc trị mụn y khoa phù hợp.", "correct": true, "emoji": "💚"}, {"text": "Mua ngay kem trị mụn siêu tốc không rõ nguồn gốc trên mạng để bôi thật dày lên toàn bộ khuân mặt.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có đang sử dụng sản phẩm làm sạch da mặt nào hàng ngày không? Nó có khiến da bạn bị khô căng sau khi rửa không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Làn da cần sự dịu dàng và kiên nhẫn chăm sóc, đừng trừng phạt nó bằng cách cậy nặn thô bạo."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson5_id, 'Vệ sinh vùng nhạy cảm đúng khoa học', 3);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có biết vùng kín của cơ thể đòi hỏi một chế độ làm sạch đặc biệt tinh tế và cẩn thận?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Vùng nhạy cảm có độ pH tự nhiên cân bằng để tự bảo vệ trước nấm và vi khuẩn có hại.", "**Quy tắc làm sạch**: Đối với nữ, chỉ rửa sạch bên ngoài âm hộ bằng nước sạch hoặc dung dịch vệ sinh dịu nhẹ, tuyệt đối không thụt rửa sâu vào âm đạo. Đối với nam, cần nhẹ nhàng kéo bao quy đầu để làm sạch bựa sinh dục tích tụ bên dưới.", "Luôn lau khô vùng kín từ trước ra sau (đối với nữ) sau khi đi vệ sinh để tránh lây nhiễm vi khuẩn từ hậu môn."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống viêm nhiễm", "body": "Vy thấy vùng kín ngứa ngáy và ra khí hư màu trắng đục. Nghĩ rằng do mình chưa rửa sạch, Vy dùng xà bông tắm chà xát thật mạnh và thụt vòi sen rửa sâu vào trong âm đạo. Kết quả là Vy thấy rát buốt và ngứa nặng hơn."}', 3),
(@ml_id, 'interaction', '{"question": "Hành động thụt rửa bằng xà bông của Vy sai lầm ở điểm nào?", "choices": [{"text": "Xà bông tắm và việc thụt rửa sâu đã phá vỡ sự cân bằng pH và tiêu diệt các lợi khuẩn bảo vệ âm đạo.", "correct": true, "emoji": "💚"}, {"text": "Vy dùng chưa đủ lượng xà bông sát khuẩn mạnh, cần ngâm rửa bằng nước muối đặc hoặc cồn y tế để diệt trùng.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã nắm rõ quy trình vệ sinh vùng nhạy cảm an toàn hàng ngày cho bản thân chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Vùng kín có cơ chế tự làm sạch tuyệt vời, hãy đối xử với nó bằng sự nhẹ nhàng nhất."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson5_id, 'Giấc ngủ và năng lượng phục hồi', 4);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Tại sao bộ não của bạn lại cần đến 9 tiếng ngủ mỗi đêm để dọn dẹp các mảnh rác thông tin?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Trong lúc ngủ, cơ thể sản sinh ra hormone tăng trưởng (growth hormone) mạnh mẽ nhất giúp phát triển xương và cơ bắp.", "Bộ não tuổi dậy thì đang trong giai đoạn tái cấu trúc, rất cần giấc ngủ sâu để củng cố trí nhớ và ổn định cảm xúc.", "Thiếu ngủ kéo dài (dưới 8 tiếng) sẽ dẫn tới mất tập trung, dễ cáu gắt, suy giảm hệ miễn dịch và còi cọc chiều cao."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống cú đêm", "body": "Hoàng có thói quen thức đến 1-2 giờ sáng để lướt TikTok và chơi game cùng nhóm bạn. Sáng hôm sau Hoàng thức dậy trong trạng thái đầu óc mụ mị, ngủ gật trong giờ học và luôn thấy bực bội vô cớ."}', 3),
(@ml_id, 'interaction', '{"question": "Hoàng nên thay đổi thói quen giấc ngủ thế nào để lấy lại năng lượng học tập?", "choices": [{"text": "Thiết lập ranh giới ngủ: Cất điện thoại khỏi giường trước khi ngủ 30 phút, cố gắng ngủ đủ 8-9 tiếng mỗi đêm.", "correct": true, "emoji": "💚"}, {"text": "Tiếp tục thức khuya chơi game, bù lại bằng cách ngủ nướng đến trưa vào ngày cuối tuần.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Giờ ngủ trung bình hàng đêm của bạn là mấy giờ? Bạn có cảm thấy sảng khoái khi thức dậy vào buổi sáng không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Giấc ngủ là chiếc sạc pin tự nhiên và miễn phí tốt nhất dành cho sức khỏe của bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson5_id, 'Dinh dưỡng xây dựng thể chất', 5);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có biết cơ thể bạn đang cần những khối gạch xây dựng nào để bứt phá chiều cao tuổi dậy thì?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Dinh dưỡng tuổi dậy thì cần ưu tiên bổ sung đầy đủ protein (thịt, cá, trứng), canxi (sữa, rau xanh) để xây dựng hệ xương vững chắc.", "Uống đủ nước (khoảng 1.5 - 2 lít mỗi ngày) giúp thanh lọc cơ thể, làm da ẩm mượt và giảm mụn trứng cá.", "Hạn chế các đồ ăn nhanh nhiều dầu mỡ, nước ngọt có ga vì chúng làm tăng nguy cơ béo phì và cản trở hấp thụ canxi."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống bỏ bữa", "body": "Vy thường xuyên bỏ bữa sáng vì dậy muộn, bữa trưa chỉ ăn mì tôm hoặc trà sữa trân châu kèm khoai tây chiên giòn vì thấy ngon miệng. Vy thấy tóc mình rụng nhiều và móng tay rất dễ gãy."}', 3),
(@ml_id, 'interaction', '{"question": "Chế độ ăn của Vy đang thiếu hụt những dưỡng chất quan trọng nào cho sự phát triển?", "choices": [{"text": "Thiếu protein, vitamin và các vi chất", "correct": true, "emoji": "💚"}, {"text": "Không thiếu gì cả, trà sữa đã có sữa cung cấp canxi và mì tôm đã có tinh bột cung cấp năng lượng đầy đủ.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Hôm nay bạn đã uống đủ nước và ăn loại rau quả tươi xanh nào chưa?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Bạn chính là những gì bạn ăn, hãy cung cấp nguyên liệu tốt nhất để cơ thể xây dựng vóc dáng tương lai."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson5_id, 'Thói quen vận động lành mạnh', 6);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để giải phóng năng lượng dư thừa và dập tắt những suy nghĩ căng thẳng, ủ dột trong đầu?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Vận động thể chất kích thích não bộ tiết ra endorphins - hormone hạnh phúc giúp giảm stress và cải thiện tâm trạng cực nhanh.", "Tập thể thao (như bơi lội, bóng rổ, chạy bộ, nhảy hiện đại) giúp kéo dài xương, săn chắc cơ bắp và nâng cao sức bền.", "Chỉ cần 30-45 phút vận động mỗi ngày là bạn đã giúp cơ thể phát triển tối đa tiềm năng chiều cao của mình."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống ủ dột", "body": "An thấy tâm trạng uể oải, lo lắng trước kỳ thi học kỳ. An chọn cách nằm dài trên giường lướt mạng xã hội liên tục 4 tiếng. Kết quả là An thấy đầu óc càng thêm mệt mỏi và đau ê ẩm vai gáy."}', 3),
(@ml_id, 'interaction', '{"question": "An nên làm gì thay vì nằm lướt điện thoại để giải tỏa căng thẳng hiệu quả?", "choices": [{"text": "Xỏ giày đi bộ công viên, đạp xe hoặc tham gia một trận bóng rổ ngắn cùng các bạn hàng xóm.", "correct": true, "emoji": "💚"}, {"text": "Tiếp tục nằm lướt điện thoại để tìm các bài viết chia sẻ mẹo giảm stress trên mạng xã hội.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Môn thể thao hoặc hoạt động vận động nào khiến bạn cảm thấy sảng khoái và tràn đầy năng lượng nhất?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Vận động cơ thể là cách tuyệt vời nhất để dọn dẹp đống lộn xộn trong tâm trí."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson5_id, 'Bài kiểm tra: Thử thách tổng kết', 99);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Chào mừng bạn đến với Thử thách Tổng kết bài học ''Vệ sinh cá nhân & Chăm sóc cơ thể''! Cùng nâng cao kỹ năng vệ sinh và thiết lập thói quen sinh hoạt khoa học."}', 1),
(@ml_id, 'scenario-choice', '{"title": "Khử mùi hôi nách và xử lý kích ứng da", "startNode": "step1", "nodes": {"step1": {"text": "Đức bị mùi cơ thể khá nặng sau mỗi buổi tập bóng rổ. Bạn bè bắt đầu xì xào làm Đức rất xấu hổ. Đức muốn khử mùi nách nhanh chóng.", "choices": [{"text": "Dùng chanh tươi chà xát thật mạnh lên nách liên tục nhiều lần mỗi ngày.", "nextNode": "fail_lemon"}, {"text": "Tắm rửa sạch sẽ bằng xà phòng dịu nhẹ sau khi chơi thể thao, lau khô nách.", "nextNode": "step2"}]}, "step2": {"text": "Nách Đức vẫn đổ nhiều mồ hôi ẩm ướt. Đức băn khoăn nên chọn sản phẩm nào để kiểm soát mồ hôi nách.", "choices": [{"text": "Dùng nước hoa xịt đè trực tiếp lên vùng da nách đang ướt đẫm mồ hôi.", "nextNode": "fail_perfume"}, {"text": "Phân biệt rõ loại lăn khử mùi (deodorant) và lăn ngăn mồ hôi (antiperspirant) để thoa lên nách khô ráo.", "nextNode": "step3"}]}, "step3": {"text": "Đức phát hiện vùng da dưới cánh tay bị mẩn đỏ và ngứa rát dữ dội sau khi dùng một loại lăn ngăn mồ hôi mới mua trên mạng.", "choices": [{"text": "Nghĩ là phản ứng bình thường, tiếp tục lăn đè lên vết đỏ để khử mùi.", "nextNode": "fail_allergy"}, {"text": "Ngưng sử dụng ngay lập tức, rửa sạch nách bằng nước ấm và để nách thông thoáng phục hồi.", "nextNode": "step4"}]}, "step4": {"text": "Đức thường thức khuya lướt mạng xã hội đến 1 giờ sáng để thư giãn, dẫn đến sáng ngủ dậy rất mệt mỏi và nách đổ nhiều mồ hôi hơn.", "choices": [{"text": "Thiết lập lịch ngủ sớm trước 11 giờ tối để hồi phục năng lượng và điều hòa hệ nội tiết.", "nextNode": "step5"}, {"text": "Uống cà phê đậm đặc vào sáng sớm để duy trì sự tỉnh táo mà không cần thay đổi lịch ngủ.", "nextNode": "fail_coffee"}]}, "step5": {"text": "Khi đi tắm, Đức thấy bao quy đầu của mình có bám cặn trắng (bựa sinh dục) có mùi hôi. Bạn mách Đức dùng xà phòng tắm chà rửa mạnh vào đầu dương vật.", "choices": [{"text": "Dùng xà phòng tắm chứa chất tẩy rửa mạnh chà xát thật lực để sạch bựa sinh dục.", "nextNode": "fail_soap"}, {"text": "Nhẹ nhàng kéo bao quy đầu về phía sau, rửa sạch bựa sinh dục bằng nước ấm và lau khô.", "nextNode": "success_end"}]}, "success_end": {"text": "🎉 Hoàn thành xuất sắc! Bạn đã biết cách khử mùi cơ thể khoa học, xử lý kích ứng da, ngủ nghỉ điều độ và vệ sinh bao quy đầu đúng cách.", "isEnd": true, "isSuccess": true}, "fail_lemon": {"text": "❌ Chưa đúng! Axit citric trong chanh chà xát trực tiếp lên nách làm bào mòn da, gây kích ứng, rát đỏ và thâm đen vùng nách.", "isEnd": true, "isSuccess": false}, "fail_perfume": {"text": "❌ Chưa đúng! Xịt nước hoa đè lên mồ hôi tạo ra hỗn hợp mùi chua nồng rất khó chịu cho mọi người xung quanh.", "isEnd": true, "isSuccess": false}, "fail_allergy": {"text": "❌ Sai rồi! Tiếp tục dùng sản phẩm gây kích ứng có thể làm nách bị viêm da tiếp xúc, lở loét và nhiễm trùng nặng.", "isEnd": true, "isSuccess": false}, "fail_coffee": {"text": "❌ Sai rồi! Uống cà phê ép não hoạt động khi thiếu ngủ làm tăng tiết cortisol (stress hormone) khiến nách đổ mồ hôi nặng mùi hơn.", "isEnd": true, "isSuccess": false}, "fail_soap": {"text": "❌ Sai rồi! Da đầu dương vật và bao quy đầu cực kỳ nhạy cảm, chà rửa bằng xà phòng kiềm mạnh gây rát bỏng và viêm nhiễm đầu dương vật.", "isEnd": true, "isSuccess": false}}}', 2),
(@ml_id, 'sorting', '{"instruction": "Hãy phân loại các thói quen chăm sóc sức khỏe dậy thì sau:", "leftBox": {"title": "Thói quen tốt (Green Flag)"}, "rightBox": {"title": "Thói quen xấu (Red Flag)"}, "items": [{"text": "Tắm rửa lau khô sau khi chơi thể thao", "correctBox": "left"}, {"text": "Chà xát chanh tươi trực tiếp lên nách", "correctBox": "right"}, {"text": "Chọn lăn ngăn mồ hôi khi nách đổ dầu nhiều", "correctBox": "left"}, {"text": "Dùng nước hoa xịt thẳng lên mồ hôi ướt", "correctBox": "right"}, {"text": "Giặt sạch đồ lót mỗi ngày sau khi tắm", "correctBox": "left"}, {"text": "Mặc lại quần áo thể thao đẫm mồ hôi hôm qua", "correctBox": "right"}, {"text": "Rửa đầu dương vật nhẹ nhàng bằng nước ấm", "correctBox": "left"}, {"text": "Lăn khử mùi đè trực tiếp lên da nách đang viêm loét", "correctBox": "right"}, {"text": "Đi ngủ sớm trước 11 giờ tối để phát triển chiều cao", "correctBox": "left"}, {"text": "Thức khuya lướt điện thoại đến 2 giờ sáng", "correctBox": "right"}]}', 3),
(@ml_id, 'matching', '{"instruction": "Ghép cặp các phương pháp vệ sinh vùng nhạy cảm đúng khoa học:", "pairs": [{"left": "Deodorant", "right": "Sản phẩm chứa chất diệt khuẩn giúp khử mùi hôi nách"}, {"left": "Antiperspirant", "right": "Lăn ngăn mồ hôi chứa muối nhôm tạm khóa tuyến mồ hôi"}, {"left": "Dị ứng lăn nách", "right": "Triệu chứng mẩn đỏ, ngứa rát cần ngưng dùng ngay"}, {"left": "Bao quy đầu", "right": "Cần kéo nhẹ để rửa sạch bựa sinh dục bên dưới bằng nước ấm"}, {"left": "Vệ sinh vùng nữ", "right": "Chỉ rửa nhẹ nhàng âm hộ bên ngoài, không thụt rửa sâu"}, {"left": "Sấy khô vùng kín", "right": "Dùng khăn mềm thấm khô trước khi mặc quần lót sạch"}, {"left": "Bựa sinh dục", "right": "Chất cặn trắng đọng ở rãnh quy đầu nếu vệ sinh kém"}, {"left": "Hormone tăng trưởng", "right": "Chất kích thích chiều cao tiết ra nhiều nhất khi ngủ sâu"}]}', 4),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 1: Điền từ thích hợp về cơ chế khử mùi cơ thể tuổi dậy thì:", "sentence": "Mùi cơ thể phát sinh khi mồ hôi tương tác với vi khuẩn trên da. Lăn khử mùi (deodorant) chứa chất [blank1] để khử mùi hôi, còn lăn ngăn mồ hôi (antiperspirant) chứa muối [blank2] giúp khóa tuyến mồ hôi tạm thời. Bạn nên thoa các sản phẩm này lên vùng da nách đã được lau [blank3]. Nếu vùng da nách bị [blank4] đỏ và ngứa rát, hãy ngưng sử dụng ngay lập tức. Đừng lạm dụng nước hoa để [blank5] lên mồ hôi ướt vì sẽ tạo ra mùi chua nồng khó chịu.", "blanks": {"blank1": {"correct": "diệt khuẩn", "placeholder": "..."}, "blank2": {"correct": "nhôm", "placeholder": "..."}, "blank3": {"correct": "khô ráo", "placeholder": "..."}, "blank4": {"correct": "mẩn", "placeholder": "..."}, "blank5": {"correct": "xịt đè", "placeholder": "..."}}, "words": ["diệt khuẩn", "nhôm", "khô ráo", "mẩn", "xịt đè", "tạo mùi", "sắt", "ẩm ướt", "tróc", "pha loãng"]}', 5),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 2: Điền từ thích hợp về vệ sinh vùng kín và giấc ngủ dậy thì:", "sentence": "Cơ quan sinh dục cần được vệ sinh hàng ngày bằng nước sạch hoặc dung dịch vệ sinh có [blank1] phù hợp. Bạn trai chưa cắt bao quy đầu cần nhẹ nhàng [blank2] lớp da để làm sạch bựa sinh dục tích tụ bên trong. Bên cạnh vệ sinh, giấc ngủ sâu trước [blank3] là thời điểm cơ thể tiết ra [blank4] tăng trưởng mạnh nhất. Thiếu ngủ liên tục sẽ làm suy giảm [blank5] và cản trở sự phát triển chiều cao tự nhiên.", "blanks": {"blank1": {"correct": "độ pH", "placeholder": "..."}, "blank2": {"correct": "kéo ngược", "placeholder": "..."}, "blank3": {"correct": "11 giờ tối", "placeholder": "..."}, "blank4": {"correct": "hormone", "placeholder": "..."}, "blank5": {"correct": "sự tập trung", "placeholder": "..."}}, "words": ["độ pH", "kéo ngược", "11 giờ tối", "hormone", "sự tập trung", "hóa chất", "cắt bỏ", "1 giờ sáng", "độc tố", "chiều cao"]}', 6),
(@ml_id, 'interaction', '{"question": "Khi bị ngứa ngáy mẩn đỏ và rát nách sau khi dùng lăn khử mùi mới, hành động nào là đúng?", "choices": [{"text": "Ngưng dùng ngay lập tức, rửa nách bằng nước ấm sạch và để da phục hồi tự nhiên.", "correct": true, "emoji": "💚"}, {"text": "Tiếp tục dùng lăn khử mùi đó kết hợp bôi cồn sát trùng nách cho hết vi khuẩn.", "correct": false, "emoji": "🛑"}]}', 7),
(@ml_id, 'interaction', '{"question": "Sự khác biệt cốt lõi giữa lăn khử mùi (deodorant) và lăn ngăn mồ hôi (antiperspirant) là gì?", "choices": [{"text": "Deodorant diệt khuẩn chống mùi hôi; Antiperspirant giảm tiết mồ hôi giữ nách khô ráo.", "correct": true, "emoji": "💚"}, {"text": "Deodorant chỉ dùng cho bạn gái; Antiperspirant chỉ dùng cho bạn trai thể thao.", "correct": false, "emoji": "🛑"}]}', 8),
(@ml_id, 'interaction', '{"question": "Thói quen vệ sinh vùng kín của bạn trai chưa cắt bao quy đầu chuẩn khoa học là như thế nào?", "choices": [{"text": "Nhẹ nhàng kéo bao quy đầu về phía sau, rửa đầu dương vật bằng nước ấm sạch mỗi ngày.", "correct": true, "emoji": "💚"}, {"text": "Dùng xà phòng tắm chứa hương liệu chà xát thật mạnh vào bao quy đầu để sát khuẩn.", "correct": false, "emoji": "🛑"}]}', 9),
(@ml_id, 'interaction', '{"question": "Cận trắng (bựa sinh dục) đọng lâu ngày dưới lớp da bao quy đầu bạn trai do lười vệ sinh có thể gây ra hậu quả gì?", "choices": [{"text": "Kích ứng, gây mùi hôi nồng nặc và tăng nguy cơ viêm nhiễm quy đầu dương vật.", "correct": true, "emoji": "💚"}, {"text": "Gây teo tinh hoàn và ngăn cản sự sản xuất tinh dịch vĩnh viễn.", "correct": false, "emoji": "🛑"}]}', 10),
(@ml_id, 'interaction', '{"question": "Thời điểm lý tưởng nhất để cơ thể tiết ra hormone tăng trưởng tối đa thúc đẩy chiều cao là lúc nào?", "choices": [{"text": "Khi bạn đang ngủ thật sâu trong khoảng từ 11 giờ tối đến 2 giờ sáng.", "correct": true, "emoji": "💚"}, {"text": "Khi bạn đang tập luyện thể thao cường độ mạnh vào ban ngày.", "correct": false, "emoji": "🛑"}]}', 11);
INSERT INTO lessons (course_id, slug, title, summary, content, lesson_order, is_free, xp_reward, estimated_minutes)
INSERT INTO lesson_sources (lesson_id, source_name, source_url, source_type) VALUES
(@lesson6_id, 'Scarleteen - Body Image', 'https://www.scarleteen.com/read/body-image', 'website');
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson6_id, 'Nhận thức về ngoại hình là gì?', 1);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn nhìn nhận cơ thể mình bằng con mắt yêu thương, hay bằng ống kính săm soi của người khác?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Nhận thức ngoại hình (Body Image) là tổng hợp những cảm xúc, suy nghĩ và thái độ của bạn về vẻ bề ngoài của chính mình.", "Body image có thể tích cực (yêu quý, trân trọng cơ thể) hoặc tiêu cực (luôn thấy tự ti, xấu hổ, muốn thay đổi phẫu thuật).", "Một body image tích cực giúp bạn tự tin thể hiện bản thân và có sức khỏe tinh thần vững vàng trước áp lực xung quanh."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống tự ti", "body": "Linh luôn thấy mình có đùi to và da ngăm đen. Linh từ chối đi dã ngoại cùng lớp vì sợ phải mặc quần shorts ngắn lộ khuyết điểm. Linh luôn nghĩ mọi người sẽ cười nhạo chân mình."}', 3),
(@ml_id, 'interaction', '{"question": "Linh nên thay đổi góc nhìn về đôi chân của mình như thế nào để thấy thoải mái hơn?", "choices": [{"text": "Trân trọng việc đôi chân khỏe mạnh đã giúp mình đi lại, chạy nhảy, chơi cầu lông và khám phá nhiều nơi.", "correct": true, "emoji": "💚"}, {"text": "Nhịn ăn và tìm cách bôi kem làm trắng siêu tốc để chân thon nhỏ và trắng trẻo bằng mọi giá trước khi dám ra đường.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có thường cảm thấy tự ti về một bộ phận nào đó trên cơ thể mình không? Bạn có muốn làm hòa với nó không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Ngoại hình chỉ là vỏ bọc, năng lực và tâm hồn mới là thứ tạo nên sức hút thực sự của bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson6_id, 'Sự thao túng của mạng xã hội', 2);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có biết đằng sau những bức ảnh eo thon, da trắng không tì vết trên mạng là gì không?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Hầu hết hình ảnh trên mạng xã hội đều đã qua chỉnh sửa bằng filter bóp dáng, photoshop mịn da và chọn góc chụp ánh sáng hoàn hảo.", "Việc liên tục xem những hình mẫu phi thực tế này tạo nên tiêu chuẩn sắc đẹp ảo, khiến bạn ảo tưởng và tự ti về cơ thể tự nhiên của mình.", "Hãy tập thói quen thanh lọc mạng xã hội (digital detox), ngưng theo dõi những tài khoản độc hại làm bạn thấy tệ hại."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống lướt mạng", "body": "Hân nằm xem Instagram và thấy các hot girl khoe eo thon phẳng lì không một nếp gấp khi ngồi. Hân nhìn xuống bụng mình khi ngồi thấy có một ngấn mỡ nhỏ và thấy vô cùng thất vọng, ghét bỏ bản thân."}', 3),
(@ml_id, 'interaction', '{"question": "Hân nên nhắc nhở bản thân điều gì để tránh bị thao túng bởi hình ảnh eo thon trên mạng?", "choices": [{"text": "Khi ngồi, da và mỡ bụng co lại tạo nếp gấp là phản ứng vật lý tự nhiên của mọi cơ thể sống để bảo vệ nội tạng.", "correct": true, "emoji": "💚"}, {"text": "Chắc chắn do mình béo quá rồi, phải mua đai nịt bụng nén chặt lại suốt 24h để eo thon phẳng lì như họ.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Mạng xã hội có bao giờ làm bạn thấy nghi ngờ hay ghét bỏ vẻ bề ngoài tự nhiên của mình không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Đừng so sánh cơ thể thực tế của bạn với những tác phẩm chỉnh sửa kỹ thuật số trên mạng."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson6_id, 'Vượt qua định kiến miệt thị ngoại hình', 3);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn sẽ làm gì khi những lời trêu chọc ác ý vô duyên nhắm thẳng vào cân nặng hay chiều cao của bạn?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Miệt thị ngoại hình (body shaming) là hành vi dùng lời nói chê bai, giễu cợt ngoại hình của người khác làm trò cười.", "Lời chê bai phản ánh định kiến hẹp hòi và sự kém tinh tế của người nói, hoàn toàn không định nghĩa giá trị thực tế của bạn.", "Hãy thiết lập ranh giới dứt khoát, không cười hùa theo những trò đùa khiếm nhã làm tổn hại lòng tự trọng."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống bị trêu", "body": "Trong giờ ra chơi, Nam bị một nhóm bạn nam cười cợt và gọi là \"thằng lùn tịt\" hay \"nấm độc\" trước mặt cả lớp. Nam thấy xấu hổ, tức giận muốn khóc và muốn bỏ về nhà ngay lập tức."}', 3),
(@ml_id, 'interaction', '{"question": "Nam nên phản ứng dứt khoát như thế nào để bảo vệ bản thân trước nhóm bạn body shaming?", "choices": [{"text": "Nhìn thẳng vào họ, nói nghiêm túc: ''Tớ không thích cách các cậu trêu chọc chiều cao của tớ đâu. Dừng lại đi!'' rồi đi chỗ khác.", "correct": true, "emoji": "💚"}, {"text": "Cố cười gượng gạo hùa theo để mọi người thấy mình là người cởi mở, không chấp nhặt đùa vui.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có từng vô tình trêu chọc ngoại hình của ai đó để làm trò đùa chưa? Bạn nghĩ họ sẽ cảm thấy thế nào?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Lời chê bai của người khác không định nghĩa bạn là ai, cách bạn phản ứng mới thể hiện bản lĩnh của bạn."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson6_id, 'Hội chứng ám ảnh cân nặng', 4);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Có phải việc sở hữu một cơ thể gầy gò xương xẩu mới được coi là đẹp và khỏe mạnh?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Ám ảnh cân nặng có thể dẫn đến các rối loạn ăn uống (eating disorders) nguy hiểm như chán ăn tâm thần hoặc cuồng ăn vô độ.", "Cơ thể khỏe mạnh có nhiều hình dáng, kích thước khác nhau (đậm người, mình dây, cơ bắp) tùy thuộc vào cơ địa.", "Mục tiêu đúng đắn là hướng tới sự khỏe mạnh, dẻo dai bên trong thông qua thói quen ăn uống, vận động khoa học thay vì chỉ số cân nặng."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống nhịn ăn", "body": "Vân muốn có thân hình mảnh mai như người mẫu nên quyết định nhịn ăn bữa tối hoàn toàn và chỉ uống nước lọc. Sau 2 tuần, Vân thấy chóng mặt, rụng tóc và không thể tập trung học bài được."}', 3),
(@ml_id, 'interaction', '{"question": "Thói quen ăn uống của Vân đang gây ra tác hại gì cho cơ thể?", "choices": [{"text": "Nhịn ăn làm cơ thể thiếu năng lượng nuôi não bộ, suy dinh dưỡng và cản trở sự phát triển chiều cao tuổi dậy thì.", "correct": true, "emoji": "💚"}, {"text": "Không sao cả, đây là quá trình thanh lọc cơ thể cần thiết để đào thải mỡ thừa, giúp Vân có vóc dáng thon thả nhanh chóng.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có đang đánh giá sức khỏe của mình dựa trên con số hiển thị trên chiếc cân mỗi ngày không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Cân nặng chỉ là một con số, sự dẻo dai và tràn đầy năng lượng mới là thước đo sức khỏe thực sự."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson6_id, 'Trân trọng sự độc bản cơ thể', 5);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có sẵn lòng ký bản thỏa thuận hòa bình và chấp nhận cơ thể độc nhất vô nhị của chính mình?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Chấp nhận cơ thể (body acceptance) là học cách sống hòa bình với những khía cạnh ngoại hình không thể thay đổi (như chiều cao, màu da, dáng xương).", "Bạn không cần phải hoàn hảo để xứng đáng được yêu quý và tôn trọng.", "Sự độc bản (uniqueness) chính là nét quyến rũ riêng biệt của bạn; thế giới sẽ thật tẻ nhạt nếu ai cũng giống hệt nhau."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống làm hòa", "body": "Hoa có nụ cười răng khểnh và một vài vết tàn nhang trên má. Thay vì cố gắng đi tẩy tàn nhang hay giấu nụ cười, Hoa tự tin cười rạng rỡ và coi răng khểnh là nét duyên dáng riêng của mình."}', 3),
(@ml_id, 'interaction', '{"question": "Thái độ tự chấp nhận của Hoa mang lại lợi ích gì cho bạn ấy?", "choices": [{"text": "Giúp Hoa luôn vui vẻ, tự tin giao tiếp và tỏa ra năng lượng tích cực lôi cuốn mọi người xung quanh.", "correct": true, "emoji": "💚"}, {"text": "Làm Hoa thiếu ý chí phấn đấu hoàn thiện vẻ đẹp ngoại hình để trở nên hoàn hảo hơn.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Một khuyết điểm ngoại hình nào mà hôm nay bạn sẵn lòng mỉm cười bao dung và chấp nhận nó như nét riêng của mình?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Bạn là duy nhất trên thế giới này, hãy trân trọng sự độc bản đó như một món quà."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson6_id, 'Xây dựng lối sống tự tin bền vững', 6);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để duy trì sự tự tin ngoại hình vững vàng trước những biến động dư luận xung quanh?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Tự tin bền vững đến từ việc bạn thấu hiểu giá trị bên trong của mình và xây dựng thói quen chăm sóc sức khỏe khoa học.", "Tập trung vào những việc bạn kiểm soát được (chăm sóc vệ sinh, ăn uống đủ chất, rèn luyện kỹ năng) thay vì lo lắng về những việc ngoài tầm tay.", "Hãy bao dung và trò chuyện với chính mình bằng sự dịu dàng như cách bạn đối xử với người bạn thân yêu."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống tự thoại", "body": "Minh thi trượt cuộc thi hát của trường và bị một số bạn chê giọng khàn tai trâu. Minh buồn bã, nhưng tự nói với mình: \"Giọng mình đang dậy thì vỡ tiếng nên khàn chút là bình thường. Mình hát vì yêu thích âm nhạc, ý kiến chê bai không làm mình từ bỏ đam mê\"."}', 3),
(@ml_id, 'interaction', '{"question": "Cách tự đối thoại bằng lòng trắc ẩn của Minh giúp bạn ấy điều gì?", "choices": [{"text": "Bảo vệ lòng tự trọng tinh thần, xoa dịu nỗi buồn thất bại và tiếp tục kiên trì theo đuổi đam mê lành mạnh.", "correct": true, "emoji": "💚"}, {"text": "Khiến Minh tự mãn, ảo tưởng về giọng hát của mình và không chịu tiếp thu ý kiến đóng góp tiến bộ.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn thường tự động viên bản thân bằng câu nói ấm áp nào mỗi khi gặp chuyện buồn lòng hoặc thất bại?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Sự tự tin rực rỡ nhất là sự tự tin bắt nguồn từ lòng bao dung và trân trọng chính mình."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson6_id, 'Bài kiểm tra: Thử thách tổng kết', 99);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Chào mừng bạn đến với Thử thách Tổng kết bài học ''Ngoại hình & Thói quen lành mạnh''! Cùng xây dựng hàng rào bảo vệ làn da mụn dậy thì và chấp nhận ngoại hình."}', 1),
(@ml_id, 'scenario-choice', '{"title": "Skincare trị mụn trứng cá dậy thì", "startNode": "step1", "nodes": {"step1": {"text": "Da mặt Vy nổi cơn lốc mụn trứng cá sưng đỏ trước thềm lễ bế giảng. Vy tự ti vô cùng và lên mạng tìm kiếm cách trị mụn cấp tốc.", "choices": [{"text": "Đặt mua hũ kem trộn trị mụn thần tốc 3 ngày được quảng cáo trên Facebook.", "nextNode": "fail_cream"}, {"text": "Tìm hiểu khoa học, nhận thấy mụn dậy thì do bã nhờn kết hợp vi khuẩn, cần chăm sóc da kiên trì.", "nextNode": "step2"}]}, "step2": {"text": "Vy có một nốt mụn bọc sưng viêm lớn và đau nhức trên má. Bạn khuyên Vy dùng tay nặn nó ra ngay cho nhanh hết sưng.", "choices": [{"text": "Dùng hai đầu ngón tay chưa rửa sạch cố nặn thật mạnh nốt mụn bọc sưng đỏ.", "nextNode": "fail_squeeze"}, {"text": "Tuyệt đối không nặn, giữ da mặt sạch bằng sữa rửa mặt dịu nhẹ và chấm gel trị mụn chứa acid salicylic.", "nextNode": "step3"}]}, "step3": {"text": "Vy kiên trì skincare nhưng một tuần sau da Vy bỗng tróc vảy đỏ và nóng rát do thoa quá nhiều loại serum trị mụn cùng lúc.", "choices": [{"text": "Tiếp tục thoa đè các loại serum trị mụn liều mạnh để mụn mau xẹp.", "nextNode": "fail_overuse"}, {"text": "Tạm ngưng các serum đặc trị, chỉ duy trì sữa rửa mặt dịu nhẹ và kem dưỡng ẩm phục hồi da lành tính.", "nextNode": "step4"}]}, "step4": {"text": "Da mặt Vy đã bớt rát đỏ nhưng một số bạn cùng lớp xì xào chê da Vy nhiều sẹo thâm, khuyên Vy bôi kem đánh răng lên vết thâm mụn để làm trắng nhanh.", "choices": [{"text": "Bôi một lớp kem đánh răng dày lên các vết thâm mụn suốt cả đêm.", "nextNode": "fail_toothpaste"}, {"text": "Bôi kem chống nắng đầy đủ mỗi khi ra ngoài và kiên nhẫn để da tự phục hồi.", "nextNode": "step5"}]}, "step5": {"text": "Một người bạn khác mách Vy nên mua thuốc nam gia truyền rượu rễ cây để bôi lên mặt giúp ''thải độc da'' bong tróc mụn cũ tái tạo da mới láng mịn.", "choices": [{"text": "Bỏ qua lời khuyên phản khoa học, kiên trì chu trình dưỡng ẩm phục hồi đơn giản.", "nextNode": "success_end"}, {"text": "Mua rượu thuốc rễ cây bôi lên mặt chờ da sưng tấy bong tróc thải độc.", "nextNode": "fail_alcohol_skin"}]}, "success_end": {"text": "🎉 Hoàn thành xuất sắc! Bạn đã vượt qua bẫy kem trộn trị mụn cấp tốc, biết cách xử lý mụn bọc sưng viêm, phục hồi da và bảo vệ da an toàn.", "isEnd": true, "isSuccess": true}, "fail_cream": {"text": "❌ Chưa đúng! Các loại kem trộn cấp tốc chứa corticoid làm tàn phá hàng rào bảo vệ da, gây teo da và nổi mụn bùng phát nhiễm trùng.", "isEnd": true, "isSuccess": false}, "fail_squeeze": {"text": "❌ Chưa đúng! Tự nặn mụn bọc sưng viêm bằng tay bẩn làm đẩy vi khuẩn vào sâu trong da, gây nhiễm trùng huyết và sẹo rỗ vĩnh viễn.", "isEnd": true, "isSuccess": false}, "fail_overuse": {"text": "❌ Sai rồi! Dùng quá nhiều chất đặc trị liều cao làm da bị quá tải, bỏng hóa chất nhẹ và suy yếu hàng rào bảo vệ da.", "isEnd": true, "isSuccess": false}, "fail_toothpaste": {"text": "❌ Sai rồi! Florua và các chất làm trắng trong kem đánh răng cực kỳ kích ứng da mặt, gây bỏng rát nhẹ và làm thâm sẹo mụn đậm hơn.", "isEnd": true, "isSuccess": false}, "fail_alcohol_skin": {"text": "❌ Sai rồi! Rượu thuốc tự chế phá hủy hoàn toàn hàng rào bảo vệ da, gây dị ứng nặng, bỏng cồn và sẹo rỗ nhiễm trùng nặng nề trên mặt.", "isEnd": true, "isSuccess": false}}}', 2),
(@ml_id, 'sorting', '{"instruction": "Hãy phân loại các hành động ứng xử với làn da và ngoại hình sau:", "leftBox": {"title": "Nên làm (Skincare chuẩn)"}, "rightBox": {"title": "Tránh làm (Gây hại da)"}, "items": [{"text": "Rửa mặt sạch bằng nước ấm nhẹ nhàng", "correctBox": "left"}, {"text": "Nặn mụn bọc sưng đỏ bằng tay bẩn", "correctBox": "right"}, {"text": "Thoa kem chống nắng mỗi khi ra ngoài", "correctBox": "left"}, {"text": "Dùng kem trộn trị mụn cấp tốc 3 ngày", "correctBox": "right"}, {"text": "Ngưng đặc trị khi da bị rát đỏ, tróc vảy", "correctBox": "left"}, {"text": "Thoa kem đánh răng lên mụn cho mau xẹp", "correctBox": "right"}, {"text": "Sử dụng miếng dán hút mụn cho mụn có cồi chín", "correctBox": "left"}, {"text": "Thoa rượu thuốc rễ cây để bong tróc da mặt", "correctBox": "right"}, {"text": "Bao dung và dịu dàng với khuyết điểm cơ thể", "correctBox": "left"}, {"text": "Nhịn ăn bỏ bữa để ép cân theo tiêu chuẩn thần tượng", "correctBox": "right"}]}', 3),
(@ml_id, 'matching', '{"instruction": "Ghép cặp các khái niệm về nhận thức ngoại hình và skincare:", "pairs": [{"left": "Sữa rửa mặt dịu nhẹ", "right": "Sản phẩm làm sạch bã nhờn mà không gây khô da"}, {"left": "Nặn mụn bọc", "right": "Hành vi gây nhiễm trùng sâu và để lại sẹo rỗ"}, {"left": "Kem trộn", "right": "Sản phẩm chứa corticoid gây teo da và giãn mạch máu"}, {"left": "Kem chống nắng", "right": "Lớp màng bảo vệ da khỏi tia UV ngăn thâm mụn"}, {"left": "Bã nhờn", "right": "Chất dầu tự nhiên do tuyến bã nhờn tiết ra tuổi dậy thì"}, {"left": "Phục hồi da", "right": "Quá trình dưỡng ẩm đơn giản khi da bị kích ứng rát đỏ"}, {"left": "Corticoid", "right": "Dược chất gây nghiện da và bào mòn da trong kem trộn"}, {"left": "Lòng tự trắc ẩn", "right": "Thái độ chấp nhận và yêu thương cơ thể bất toàn của mình"}]}', 4),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 1: Điền từ thích hợp về nguyên nhân và cách chăm sóc mụn trứng cá:", "sentence": "Mụn trứng cá tuổi dậy thì hình thành do sự bùng nổ hormone kích thích tuyến [blank1] hoạt động mạnh gây tắc nghẽn lỗ chân lông. Để chăm sóc da mụn, bạn nên rửa mặt bằng sữa rửa mặt [blank2] tối đa 2 lần mỗi ngày. Tuyệt đối không tự ý [blank3] mụn bọc bằng tay bẩn vì dễ gây nhiễm trùng sâu và để lại sẹo rỗ. Tránh xa các loại [blank4] trị mụn cấp tốc chứa corticoid vì chúng tàn phá hàng rào bảo vệ da và gây [blank5] mạch máu.", "blanks": {"blank1": {"correct": "bã nhờn", "placeholder": "..."}, "blank2": {"correct": "dịu nhẹ", "placeholder": "..."}, "blank3": {"correct": "nặn", "placeholder": "..."}, "blank4": {"correct": "kem trộn", "placeholder": "..."}, "blank5": {"correct": "giãn", "placeholder": "..."}}, "words": ["bã nhờn", "dịu nhẹ", "nặn", "kem trộn", "giãn", "mồ hôi", "tẩy mạnh", "gãi", "thuốc bắc", "co"]}', 5),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 2: Điền từ thích hợp về cách vượt qua áp lực tự ti ngoại hình:", "sentence": "Áp lực đồng trang lứa và truyền thông thường khiến thanh thiếu niên cảm thấy [blank1] về vóc dáng của mình. Hãy nhớ rằng các hình ảnh trên mạng xã hội thường sử dụng [blank2] chỉnh sửa không thực tế. Thay vì khắt khe so sánh bản thân, hãy học cách đối xử với mình bằng sự [blank3]. Giá trị đích thực của một con người nằm ở phẩm chất bên trong, không nằm ở [blank4] hay lời chê bai ngoại hình từ người khác. Hãy tự tin làm chủ sự [blank5] độc bản của chính mình.", "blanks": {"blank1": {"correct": "tự ti", "placeholder": "..."}, "blank2": {"correct": "filter", "placeholder": "..."}, "blank3": {"correct": "dịu dàng", "placeholder": "..."}, "blank4": {"correct": "cân nặng", "placeholder": "..."}, "blank5": {"correct": "phát triển", "placeholder": "..."}}, "words": ["tự ti", "filter", "dịu dàng", "cân nặng", "phát triển", "tự hào", "máy ảnh", "nghiêm khắc", "chiều cao", "suy thoái"]}', 6),
(@ml_id, 'interaction', '{"question": "Khi da mặt nổi mụn bọc sưng viêm to và đau nhức, hành động nào sau đây là chuẩn y khoa nhất?", "choices": [{"text": "Không chạm tay lên mụn, giữ da sạch và dùng miếng dán hút mụn hoặc chấm gel trị mụn dịu nhẹ.", "correct": true, "emoji": "💚"}, {"text": "Dùng kim khọc nhân mụn ra rồi bôi cồn đỏ sát trùng trực tiếp lên vết thương.", "correct": false, "emoji": "🛑"}]}', 7),
(@ml_id, 'interaction', '{"question": "Tại sao việc dùng kem đánh răng bôi lên nốt mụn trứng cá lại là cờ đỏ phản khoa học?", "choices": [{"text": "Vì chất florua và chất tẩy trong kem đánh răng làm bỏng rát và thâm đen vùng da bị mụn.", "correct": true, "emoji": "💚"}, {"text": "Vì kem đánh răng chứa tinh dầu bạc hà sẽ thu hút vi khuẩn gây mụn đến nhiều hơn.", "correct": false, "emoji": "🛑"}]}', 8),
(@ml_id, 'interaction', '{"question": "Thói quen rửa mặt bằng sữa rửa mặt bao nhiêu lần mỗi ngày là phù hợp nhất cho làn da dậy thì?", "choices": [{"text": "Tối đa 2 lần mỗi ngày (sáng và tối) để làm sạch bã nhờn mà không làm mất đi độ ẩm tự nhiên của da.", "correct": true, "emoji": "💚"}, {"text": "Rửa mặt liên tục 5-6 lần mỗi ngày mỗi khi thấy mặt đổ dầu để giữ da khô thoáng tuyệt đối.", "correct": false, "emoji": "🛑"}]}', 9),
(@ml_id, 'interaction', '{"question": "Chất độc hại nào thường có trong các hũ ''kem trộn'' trị mụn thần tốc gây teo da và nổi mụn bùng phát khi ngưng dùng?", "choices": [{"text": "Corticoid.", "correct": true, "emoji": "💚"}, {"text": "Acid Salicylic.", "correct": false, "emoji": "🛑"}]}', 10),
(@ml_id, 'interaction', '{"question": "Thế nào là thái độ ''lòng tự trắc ẩn'' với ngoại hình dậy thì của bản thân?", "choices": [{"text": "Chấp nhận sự biến đổi tự nhiên của cơ thể và trò chuyện với bản thân bằng lời động viên nhẹ nhàng.", "correct": true, "emoji": "💚"}, {"text": "Ép buộc bản thân phải ăn kiêng nghiêm ngặt để có số đo cơ thể giống hệt các hình ảnh đã qua filter.", "correct": false, "emoji": "🛑"}]}', 11);
