INSERT INTO lesson_sources (lesson_id, source_name, source_url, source_type) VALUES
(@lesson7_id, 'Scarleteen - Puberty Myths & Questions', 'https://www.scarleteen.com/read/quickies', 'website');
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson7_id, 'Nhận diện các lầm tưởng phổ biến tuổi dậy thì', 1);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có từng nghe những lời khuyên kỳ quặc về tuổi dậy thì khiến bạn nửa tin nửa ngờ?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Tuổi dậy thì là chủ đề nhạy cảm, dễ phát sinh nhiều tin đồn dân gian thiếu căn cứ khoa học do sự ngại ngùng chia sẻ.", "Ví dụ: Con trai cạo râu càng nhiều râu sẽ mọc càng cứng; con gái đến ngày kinh nguyệt thì không được ăn đồ chua.", "Việc tin vào những lầm tưởng này có thể gây lo âu vô cớ hoặc dẫn tới các hành vi chăm sóc cơ thể sai lệch, gây hại."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống kiêng ăn", "body": "Vy đến ngày đèn đỏ và thèm ăn một quả xoài chua. Bạn thân ngăn cản gay gắt: \"Ăn chua lúc này máu kinh sẽ bị đông cứng lại trong bụng gây ung thư đấy!\". Vy sợ hãi bỏ quả xoài đi dù rất thèm."}', 3),
(@ml_id, 'interaction', '{"question": "Lời cảnh báo của bạn Vy có đúng cơ sở khoa học y khoa hay không?", "choices": [{"text": "Sai hoàn toàn! Ăn chua hay đồ ăn có vị chua không hề ảnh hưởng đến cơ chế đông máu hay co bóp tử cung trong kỳ kinh.", "correct": true, "emoji": "💚"}, {"text": "Đúng rồi, đồ chua có tính axit mạnh sẽ làm biến đổi cấu trúc máu kinh nguyệt bên trong cơ thể ngay lập tức.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Một lời khuyên kiêng cữ hay tin đồn tuổi dậy thì nào mà bạn từng nghe thấy vô lý nhất?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Kiến thức khoa học là ánh sáng dập tắt nỗi sợ hãi từ những tin đồn truyền miệng vô căn cứ."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson7_id, 'Tầm quan trọng của việc tra cứu an toàn', 2);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để tìm kiếm lời giải đáp cho những thắc mắc thầm kín về cơ thể giữa một rừng thông tin lộn xộn trên mạng?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Internet có rất nhiều thông tin hữu ích nhưng cũng đầy rẫy những nội dung sai lệch, giật gân hoặc quảng cáo sản phẩm độc hại.", "**Nguyên tắc tra cứu an toàn**: Ưu tiên tìm kiếm từ các nguồn chính thống (như WHO, UNICEF, các trang web bệnh viện uy tín, các bài viết của Scarleteen).", "Tránh tự chẩn đoán bệnh qua các bài chia sẻ giật gân không có kiểm chứng từ các tài khoản ẩn danh trên mạng xã hội."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống tra cứu", "body": "Khang thấy vùng kín mình nổi một nốt đỏ nhỏ. Khang lên Google tìm kiếm và đọc được bài viết cảnh báo: \"Nổi nốt đỏ là dấu hiệu của bệnh ung thư giai đoạn cuối\". Khang hoảng sợ mất ăn mất ngủ suốt 3 ngày."}', 3),
(@ml_id, 'interaction', '{"question": "Sai lầm của Khang khi tự tra cứu thông tin sức khỏe trên mạng là gì?", "choices": [{"text": "Quá tin vào các bài viết giật gân câu view và tự chẩn đoán bệnh một cách vội vã gây stress nặng.", "correct": true, "emoji": "💚"}, {"text": "Khang tra cứu chưa đủ nhiều, đáng ra Khang nên vào các hội nhóm ẩn danh trên Facebook để hỏi ý kiến mọi người.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn thường truy cập trang web hoặc nguồn thông tin nào mỗi khi có thắc mắc thầm kín về sức khỏe?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Google có thể cung cấp hàng triệu câu trả lời, nhưng chỉ có chuyên gia y tế mới cho bạn giải pháp chính xác nhất."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson7_id, 'Vượt qua sự bối rối khi trò chuyện với người lớn', 3);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Tại sao việc mở lời hỏi bố mẹ về những thay đổi nhạy cảm trên cơ thể lại khó khăn như leo một ngọn núi?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Sự ngại ngùng, sợ bị đánh giá hay trêu chọc là rào cản tâm lý phổ biến khiến teen khép kín trước người thân.", "Thực tế: Bố mẹ hay người lớn đều đã từng đi qua tuổi dậy thì và họ hoàn toàn thấu hiểu những bỡ ngỡ của bạn.", "Chủ động mở lời bằng những câu hỏi đơn giản, trực diện sẽ giúp phá vỡ bầu không khí gượng gạo ban đầu."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống khó nói", "body": "Nam bắt đầu mọc nhiều mụn trứng cá viêm đau trên mặt. Nam muốn xin mẹ mua sữa rửa mặt trị mụn nhưng cứ chần chừ, đứng trước cửa phòng mẹ mãi mà không dám gõ cửa mở lời vì ngại."}', 3),
(@ml_id, 'interaction', '{"question": "Cách mở lời tự nhiên và hiệu quả nhất giúp Nam vượt qua sự bối rối là gì?", "choices": [{"text": "Mở lời trực tiếp: ''Mẹ ơi, dạo này mặt con nổi nhiều mụn viêm đau quá. Mẹ hướng dẫn con cách chăm sóc da hoặc dẫn con đi khám da liễu nhé!''.", "correct": true, "emoji": "💚"}, {"text": "Nhờ em trai sang nói hộ hoặc tự lấy tiền tiết kiệm mua kem trộn trị mụn trên mạng dùng thử.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn đã bao giờ chủ động trò chuyện với bố hoặc mẹ về một thay đổi cơ thể nào chưa? Cảm giác của bạn lúc đó thế nào?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Bố mẹ chính là đồng minh lớn nhất sẵn sàng bảo vệ và chăm sóc bạn trên hành trình trưởng thành."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson7_id, 'Bản kế hoạch tự chăm sóc bản thân', 4);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn có muốn thiết kế một tấm khiên tự chăm sóc (Self-care plan) độc bản để bảo vệ sức khỏe thể chất lẫn tinh thần của mình?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Bản kế hoạch tự chăm sóc là tập hợp các thói quen lành mạnh hàng ngày được thiết kế phù hợp với nhịp sinh học của riêng bạn.", "Thói quen lành mạnh gồm: ngủ đủ 8-9 tiếng, ăn uống cân bằng đủ chất, vận động 30 phút và dành thời gian thư giãn đầu óc không màn hình điện thoại.", "Một kế hoạch cụ thể giúp bạn duy trì năng lượng tích cực ổn định và giảm thiểu tối đa stress áp lực học đường."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống kiệt sức", "body": "Mai cảm thấy kiệt sức, đầu óc quay cuồng và luôn thấy buồn nôn trước kỳ thi học kỳ do nhịn ăn tối và thức đêm học bài liên tục suốt 1 tuần."}', 3),
(@ml_id, 'interaction', '{"question": "Mai nên điều chỉnh lối sống của mình như thế nào trong bản kế hoạch tự chăm sóc bản thân?", "choices": [{"text": "Sắp xếp thời gian biểu học tập khoa học, đi ngủ trước 11h đêm, ăn uống đủ bữa và dành 15 phút đi bộ thư giãn nạp lại năng lượng.", "correct": true, "emoji": "💚"}, {"text": "Tiếp tục cố gắng gồng mình học bài xuyên đêm, uống thêm cà phê đậm đặc để ép bộ não hoạt động công suất cao.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Một thói quen tự chăm sóc bản thân nào mà bạn sẵn lòng thực hiện ngay từ ngày hôm nay để nâng cao sức khỏe?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Tự chăm sóc bản thân không phải là ích kỷ, đó là trách nhiệm đầu tiên của bạn với chính cuộc đời mình."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson7_id, 'Lắng nghe tín hiệu kêu cứu của cơ thể', 5);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Làm sao để nhận biết cơ thể bạn đang phát đi những tín hiệu SOS cầu cứu khẩn cấp?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Cơ thể luôn giao tiếp với bạn qua các biểu hiện vật lý: đau đầu, rụng tóc nhiều, mệt mỏi kéo dài, đau quặn bụng dưới hay tâm trạng u uất trốn tránh giao tiếp.", "Đừng bao giờ phớt lờ hay coi nhẹ những tín hiệu này; chúng là tiếng kêu cứu cho thấy hệ thống sinh học bên trong đang bị quá tải hoặc gặp trục trặc.", "Chủ động tìm kiếm sự trợ giúp y tế hoặc tư vấn tâm lý đúng lúc là hành động dũng cảm tự chịu trách nhiệm với bản thân."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống SOS", "body": "Vy phát hiện vùng kín của mình bị ngứa rát dữ dội, khí hư ra nhiều có mùi hôi và đi tiểu buốt liên tục suốt 5 ngày nay. Vy sợ hãi giấu kín, không dám nói với ai vì nghĩ mình mắc bệnh xấu xa."}', 3),
(@ml_id, 'interaction', '{"question": "Vy nên hành động như thế nào trước những tín hiệu kêu cứu này của cơ thể?", "choices": [{"text": "Vượt qua sự ngượng ngùng, chia sẻ thật lòng với mẹ để được đưa đi khám bác sĩ phụ sản khoa sớm để điều trị.", "correct": true, "emoji": "💚"}, {"text": "Tiếp tục im lặng chịu đựng, tự mua các loại nước lá về ngâm rửa theo mẹo truyền miệng trên mạng xã hội.", "correct": false, "emoji": "😐"}]}', 4),
(@ml_id, 'reflection', '{"question": "Bạn có đang phớt lờ một cơn đau hay tín hiệu mệt mỏi bất thường nào trên cơ thể mình dạo gần đây không?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Lắng nghe cơ thể kêu cứu và đi khám y khoa kịp thời là biểu hiện cao nhất của sự trưởng thành."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson7_id, 'Tự tin bước vào tuổi trưởng thành', 6);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Bạn đã sẵn sàng bước tiếp trên hành trình trưởng thành đầy thú vị với một cơ thể khỏe mạnh và tâm hồn tự tin chưa?"}', 1),
(@ml_id, 'explanation', '{"bullets": ["Tuổi dậy thì là cánh cửa mở ra một chương mới đầy sắc màu và thử thách trong cuộc đời của bạn.", "Đi qua những bỡ ngỡ, lúng túng ban đầu, bạn sẽ dần làm chủ được những thay đổi sinh học và xây dựng bản sắc cá nhân vững chắc.", "Hãy luôn duy trì sự tò mò khoa học, trân trọng bản thân và đối xử tử tế bao dung với cơ thể độc bản của mình."]}', 2),
(@ml_id, 'scenario', '{"title": "Tình huống trưởng thành", "body": "Đức nhìn lại hành trình 1 năm dậy thì của mình: từ một cậu bé thấp còi, hay e thẹn ngượng ngùng nay đã cao lớn khỏe mạnh, tự tin tham gia câu lạc bộ ghi-ta trường và biết tự cạo râu vệ sinh sạch sẽ. Đức thấy tự hào về bản thân."}', 3),
(@ml_id, 'interaction', '{"question": "Sự tự hào và tự tin của Đức có được nhờ yếu tố cốt lõi nào?", "choices": [{"text": "Nhờ sự kiên nhẫn lắng nghe cơ thể, trang bị kiến thức khoa học và chủ động học tập thói quen lành mạnh.", "correct": true, "emoji": "💚"}, {"text": "Nhờ may mắn tự nhiên lớn lên mà không cần phải quan tâm chăm sóc hay học hỏi bất kỳ kỹ năng nào.", "correct": false, "emoji": "🛑"}]}', 4),
(@ml_id, 'reflection', '{"question": "Một mục tiêu lớn nhất nào về sức khỏe hay sự phát triển bản thân mà bạn muốn đặt ra cho mình trong năm nay?"}', 5),
(@ml_id, 'takeaway', '{"items": ["Trưởng thành là một đặc ân, hãy bước đi trên hành trình đó với cái đầu ngẩng cao và lòng trắc ẩn ấm áp."]}', 6);
INSERT INTO micro_lessons (lesson_id, title, micro_order) VALUES (@lesson7_id, 'Bài kiểm tra: Thử thách tổng kết', 99);
INSERT INTO micro_lesson_blocks (micro_lesson_id, block_type, content_json, order_index) VALUES
(@ml_id, 'hook', '{"title": "Chào mừng bạn đến với Thử thách Tổng kết bài học ''Giải mã lầm tưởng & Chăm sóc bản thân''! Hãy hoàn thành chặng cuối để gạt bỏ tin đồn nhảm học đường."}', 1),
(@ml_id, 'scenario-choice', '{"title": "Tự bảo vệ sức khỏe và gạt bỏ lầm tưởng", "startNode": "step1", "nodes": {"step1": {"text": "Khánh nghe các bạn rỉ tai nhau rằng hành vi tự khám phá cơ thể (thủ dâm) sẽ làm suy giảm trí nhớ, hỏng thận và gây vô sinh nam. Khánh hoang mang.", "choices": [{"text": "Âm thầm mua các loại thuốc bổ thận tráng dương trên mạng về tự uống để cứu vãn sức khỏe.", "nextNode": "fail_pills"}, {"text": "Tìm kiếm thông tin khoa học tại các nguồn kiểm chứng uy tín để hiểu đúng bản chất vấn đề.", "nextNode": "step2"}]}, "step2": {"text": "Khánh hiểu ra thủ dâm là bình thường, nhưng lo sợ khi phát hiện vùng kín của mình bị ngứa ngáy và mẩn đỏ sau khi thực hiện hành vi đó.", "choices": [{"text": "Sử dụng xà phòng giặt hoặc sữa tắm hương liệu mạnh để chà rửa thật kỹ cho sạch vi khuẩn.", "nextNode": "fail_wash"}, {"text": "Vệ sinh vùng nhạy cảm bằng nước ấm sạch, lau khô bằng khăn mềm thoáng mát và mặc đồ lót cotton sạch.", "nextNode": "step3"}]}, "step3": {"text": "Vùng nhạy cảm của Khánh tiếp tục ngứa rát dữ dội và nổi vài mụn nước nhỏ. Khánh thấy rất ngượng ngùng, xấu hổ không biết nói với ai.", "choices": [{"text": "Giấu kín bệnh tình vì sợ bị coi là hư hỏng, tự tìm các bài thuốc lá truyền miệng đắp lên nốt mụn nước.", "nextNode": "fail_shame"}, {"text": "Vượt qua sự ngượng ngùng, chia sẻ thẳng thắn với bố mẹ hoặc bác sĩ y tế học đường để được đi khám da liễu kịp thời.", "nextNode": "step4"}]}, "step4": {"text": "Khánh được bác sĩ kết luận bị viêm da tiếp xúc và kê đơn kem bôi. Trên đường về, Khánh gặp một bài đăng Facebook của tài khoản ẩn danh chia sẻ rằng thuốc bôi tây y chứa độc, khuyên đắp lá nha đam tự nhiên tốt hơn.", "choices": [{"text": "Tự ý đắp lá nha đam chưa qua tiệt trùng trực tiếp lên các mụn nước vùng kín.", "nextNode": "fail_aloe"}, {"text": "Tuân thủ bôi thuốc đúng liều lượng chỉ dẫn của bác sĩ chuyên khoa da liễu.", "nextNode": "step5"}]}, "step5": {"text": "Khánh lo lắng không biết làm thế nào để xây dựng lại một lối sống lành mạnh, cân bằng để cải thiện sức khỏe toàn diện sau đợt viêm nhiễm này.", "choices": [{"text": "Lập kế hoạch Self-care cân đối ăn uống, ngủ trước 11 giờ đêm và chơi thể thao.", "nextNode": "success_end"}, {"text": "Lên mạng tìm mua các thực phẩm chức năng thải độc cơ thể siêu tốc 7 ngày.", "nextNode": "fail_detox"}]}, "success_end": {"text": "🎉 Hoàn thành xuất sắc! Bạn đã gạt bỏ nỗi sợ hãi vô lý từ tin đồn nhảm, thực hành vệ sinh an toàn, tuân thủ điều trị y khoa và thiết lập lối sống Self-care.", "isEnd": true, "isSuccess": true}, "fail_pills": {"text": "❌ Chưa đúng! Sử dụng thuốc bổ thận tráng dương trôi nổi cực kỳ hại gan thận của tuổi dậy thì và không giải quyết được lo âu tâm lý.", "isEnd": true, "isSuccess": false}, "fail_wash": {"text": "❌ Chưa đúng! Chà rửa bằng xà phòng tẩy rửa mạnh làm rách niêm mạc da mỏng vùng kín, gây viêm nhiễm da tiếp xúc nặng.", "isEnd": true, "isSuccess": false}, "fail_shame": {"text": "❌ Sai rồi! Các bệnh lý da liễu vùng kín nếu không khám y khoa sớm có thể chuyển biến nặng thành nhiễm trùng lan rộng nguy hiểm.", "isEnd": true, "isSuccess": false}, "fail_aloe": {"text": "❌ Sai rồi! Nhựa nha đam tươi chứa chất gây ngứa mạnh và đắp lá bẩn trực tiếp lên vết thương hở vùng kín gây nhiễm trùng sâu cực kỳ nguy hại.", "isEnd": true, "isSuccess": false}, "fail_detox": {"text": "❌ Sai rồi! Các sản phẩm thải độc siêu tốc không có căn cứ khoa học, dễ gây tiêu chảy và mất nước, làm suy kiệt cơ thể dậy thì.", "isEnd": true, "isSuccess": false}}}', 2),
(@ml_id, 'sorting', '{"instruction": "Hãy phân loại các nguồn thông tin và hành vi ứng xử với sức khỏe dậy thì:", "leftBox": {"title": "Nguồn tin cậy / Lành mạnh"}, "rightBox": {"title": "Tin đồn / Có hại"}, "items": [{"text": "Trang thông tin y tế của WHO hoặc UNICEF", "correctBox": "left"}, {"text": "Bài chia sẻ của tài khoản TikTok ẩn danh quảng cáo thuốc", "correctBox": "right"}, {"text": "Website y khoa của bệnh viện lớn chính thống", "correctBox": "left"}, {"text": "Uống thuốc bổ thận để chữa lo âu do thủ dâm", "correctBox": "right"}, {"text": "Hỏi ý kiến bác sĩ chuyên khoa hoặc giáo viên y tế trường", "correctBox": "left"}, {"text": "Dùng xà phòng giặt đồ chà rửa để khử trùng vùng kín", "correctBox": "right"}, {"text": "Tuân thủ đơn thuốc bôi của bác sĩ da liễu", "correctBox": "left"}, {"text": "Đắp lá nha đam tươi trực tiếp lên mụn nước vùng kín", "correctBox": "right"}, {"text": "Xây dựng thời gian biểu cân bằng học tập và nghỉ ngơi", "correctBox": "left"}, {"text": "Uống nước ép thải độc detox cấp tốc thay bữa ăn chính", "correctBox": "right"}]}', 3),
(@ml_id, 'matching', '{"instruction": "Ghép cặp các phương pháp chăm sóc bản thân lành mạnh với bản chất tương ứng:", "pairs": [{"left": "Thủ dâm", "right": "Hành vi sinh lý bình thường nếu điều độ và kín đáo"}, {"left": "Khám da liễu", "right": "Giải pháp cần làm khi vùng kín nổi mụn nước ngứa rát"}, {"left": "WHO / UNICEF", "right": "Các tổ chức y tế và trẻ em uy tín toàn cầu"}, {"left": "Dung dịch vệ sinh", "right": "Nước rửa chuyên dụng dịu nhẹ có độ pH phù hợp"}, {"left": "Khí hư bất thường", "right": "Tín hiệu cảnh báo viêm nhiễm phụ khoa ở bạn gái"}, {"left": "Lập Self-care plan", "right": "Kế hoạch cân bằng học tập, giấc ngủ và thể thao"}, {"left": "Rượu thuốc rễ cây", "right": "Bài thuốc phản khoa học gây bỏng da mặt nghiêm trọng"}, {"left": "Nhiễm trùng ngược dòng", "right": "Nguy cơ khi để băng vệ sinh ẩm ướt quá 4 tiếng"}]}', 4),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 1: Điền từ thích hợp về sự thật khoa học của hành vi tự khám phá cơ thể:", "sentence": "Thủ dâm hay hành vi tự khám phá cơ thể là một hoạt động sinh lý [blank1] của tuổi dậy thì khi nhu cầu sinh lý tăng cao. Khoa học chứng minh hành vi này không gây vô sinh hay [blank2] như các tin đồn nhảm truyền tai. Tuy nhiên, bạn cần thực hiện điều độ, kín đáo và đảm bảo vệ sinh [blank3] trước và sau khi thực hiện. Nếu vùng kín có dấu hiệu nổi [blank4] nước hoặc ngứa rát kéo dài, bạn cần vượt qua xấu hổ để đi khám [blank5] ngay.", "blanks": {"blank1": {"correct": "bình thường", "placeholder": "..."}, "blank2": {"correct": "hỏng thận", "placeholder": "..."}, "blank3": {"correct": "bàn tay", "placeholder": "..."}, "blank4": {"correct": "mụn", "placeholder": "..."}, "blank5": {"correct": "da liễu", "placeholder": "..."}}, "words": ["bình thường", "hỏng thận", "bàn tay", "mụn", "da liễu", "dị thường", "yếu sinh lý", "dụng cụ", "mẩn", "nam khoa"]}', 5),
(@ml_id, 'fill-blank', '{"instruction": "Đoạn 2: Điền từ thích hợp về kỹ năng tìm kiếm nguồn thông tin y khoa đáng tin cậy:", "sentence": "Khi gặp các vấn đề sức khỏe khó nói, bạn trẻ thường có xu hướng tra cứu thông tin trên [blank1]. Hãy cẩn thận trước các tài khoản mạng xã hội [blank2] chia sẻ mẹo vặt y khoa phản khoa học để bán thuốc. Hãy ưu tiên các nguồn tin chính thống từ các bệnh viện lớn hoặc tổ chức y tế như [blank3]. Việc lập một kế hoạch [blank4] cân bằng giữa học tập, ngủ nghỉ và thể thao là chìa khóa vàng bảo vệ sức khỏe. Đừng [blank5] các tín hiệu cảnh báo mỏi mệt của cơ thể.", "blanks": {"blank1": {"correct": "internet", "placeholder": "..."}, "blank2": {"correct": "ẩn danh", "placeholder": "..."}, "blank3": {"correct": "WHO", "placeholder": "..."}, "blank4": {"correct": "self-care", "placeholder": "..."}, "blank5": {"correct": "phớt lờ", "placeholder": "..."}}, "words": ["internet", "ẩn danh", "WHO", "self-care", "phớt lờ", "sách vở", "bác sĩ", "UNICEF", "học tập", "chăm sóc"]}', 6),
(@ml_id, 'interaction', '{"question": "Khi vùng nhạy cảm nổi các nốt mụn lạ hoặc ngứa rát dữ dội kéo dài, thái độ nào là khoa học và an toàn nhất?", "choices": [{"text": "Chủ động chia sẻ với bố mẹ và đi khám chuyên khoa da liễu hoặc sản phụ khoa sớm.", "correct": true, "emoji": "💚"}, {"text": "Mua kem bôi chứa corticoid liều mạnh ngoài tiệm thuốc tự thoa lên vết ngứa rát.", "correct": false, "emoji": "🛑"}]}', 7),
(@ml_id, 'interaction', '{"question": "Đâu là sự thật khoa học về hành vi tự khám phá cơ thể (thủ dâm) ở tuổi dậy thì?", "choices": [{"text": "Là hành vi sinh lý bình thường, không gây hại cho sức khỏe nếu điều độ và kín đáo.", "correct": true, "emoji": "💚"}, {"text": "Là cờ đỏ nguy hiểm gây teo não, vô sinh và suy nhược cơ thể vĩnh viễn.", "correct": false, "emoji": "🛑"}]}', 8),
(@ml_id, 'interaction', '{"question": "Tại sao việc thụt rửa sâu vào trong âm đạo của bạn gái lại bị các bác sĩ sản phụ khoa cấm tuyệt đối?", "choices": [{"text": "Vì nó tàn phá hệ vi sinh vật có lợi Lactobacillus và làm thay đổi độ pH tự nhiên, gây viêm nhiễm.", "correct": true, "emoji": "💚"}, {"text": "Vì nước rửa sẽ tràn vào dạ dày gây ngộ độc đường tiêu hóa bên trong.", "correct": false, "emoji": "🛑"}]}', 9),
(@ml_id, 'interaction', '{"question": "Tự đắp các loại lá tươi hoặc nha đam tươi trực tiếp lên các nốt mụn ngứa ở cơ quan sinh dục có thể gây ra tai họa gì?", "choices": [{"text": "Gây dị ứng da nghiêm trọng, bỏng nhựa thực vật và nhiễm trùng loét sâu nguy hiểm.", "correct": true, "emoji": "💚"}, {"text": "Ngay lập tức gây vô sinh thứ phát ở cả bạn nam và bạn nữ dậy thì.", "correct": false, "emoji": "🛑"}]}', 10),
(@ml_id, 'interaction', '{"question": "Đâu là bản chất thực sự của các loại thuốc/trà có nhãn ''Thải độc cơ thể detox cấp tốc trong 7 ngày''?", "choices": [{"text": "Hầu hết là quảng cáo quá lời không có kiểm chứng y khoa, có thể gây mất nước, tiêu chảy hoặc tổn hại dạ dày.", "correct": true, "emoji": "💚"}, {"text": "Giải pháp khoa học tiên tiến giúp loại bỏ 100% độc tố và tăng chiều cao tối đa.", "correct": false, "emoji": "🛑"}]}', 11);
